import { describe, it, expect, vi, beforeEach } from 'vitest';
import { CancelSubscriptionUseCase } from './CancelSubscriptionUseCase';
import { SubscriptionRepository } from '../domain/repositories/SubscriptionRepository';
import { SubscriptionId } from '../domain/value-objects/SubscriptionId';
import { UserId } from '../domain/value-objects/UserId';
import { Subscription } from '../domain/entities/Subscription';
import { SubscriptionStatus } from '../domain/enums/SubscriptionStatus';
import { DomainEventPublisher } from '../domain/events/DomainEventPublisher';
import { SubscriptionCanceledEvent } from '../domain/events/SubscriptionCanceledEvent';
import { Result } from '../domain/types/Result';

describe('CancelSubscriptionUseCase', () => {
  let mockRepository: SubscriptionRepository;
  let mockEventPublisher: DomainEventPublisher;
  let useCase: CancelSubscriptionUseCase;

  beforeEach(() => {
    mockRepository = {
      findById: vi.fn(),
      save: vi.fn()
    };

    mockEventPublisher = {
      publish: vi.fn()
    };

    useCase = new CancelSubscriptionUseCase(mockRepository, mockEventPublisher);
  });

  describe('Arrange-Act-Assert Pattern', () => {
    it('should successfully cancel an active subscription and publish event', async () => {
      // Arrange
      const subscriptionId = new SubscriptionId('sub-123');
      const userId = new UserId('user-456');
      const activeSubscription = new Subscription(
        subscriptionId,
        userId,
        SubscriptionStatus.ACTIVE,
        new Date(),
        new Date(Date.now() + 86400000) // 1 day in future
      );

      vi.mocked(mockRepository.findById).mockResolvedValue(activeSubscription);
      vi.mocked(mockRepository.save).mockResolvedValue(undefined);

      // Act
      const result = await useCase.execute(subscriptionId);

      // Assert
      expect(result.isSuccess).toBe(true);
      expect(mockRepository.findById).toHaveBeenCalledWith(subscriptionId);
      expect(mockRepository.save).toHaveBeenCalledWith(
        expect.objectContaining({
          id: subscriptionId,
          status: SubscriptionStatus.CANCELLED
        })
      );
      expect(mockEventPublisher.publish).toHaveBeenCalledWith(
        expect.any(SubscriptionCanceledEvent)
      );
    });

    it('should return error when subscription is not found', async () => {
      // Arrange
      const subscriptionId = new SubscriptionId('sub-123');

      vi.mocked(mockRepository.findById).mockResolvedValue(null);

      // Act
      const result = await useCase.execute(subscriptionId);

      // Assert
      expect(result.isSuccess).toBe(false);
      expect(result.isFailure).toBe(true);
      expect(mockRepository.findById).toHaveBeenCalledWith(subscriptionId);
      expect(mockRepository.save).not.toHaveBeenCalled();
      expect(mockEventPublisher.publish).not.toHaveBeenCalled();
    });

    it('should return error when subscription is already cancelled', async () => {
      // Arrange
      const subscriptionId = new SubscriptionId('sub-123');
      const userId = new UserId('user-456');
      const cancelledSubscription = new Subscription(
        subscriptionId,
        userId,
        SubscriptionStatus.CANCELLED,
        new Date(),
        new Date(Date.now() + 86400000)
      );

      vi.mocked(mockRepository.findById).mockResolvedValue(cancelledSubscription);

      // Act
      const result = await useCase.execute(subscriptionId);

      // Assert
      expect(result.isSuccess).toBe(false);
      expect(result.isFailure).toBe(true);
      expect(mockRepository.findById).toHaveBeenCalledWith(subscriptionId);
      expect(mockRepository.save).not.toHaveBeenCalled();
      expect(mockEventPublisher.publish).not.toHaveBeenCalled();
    });
  });
});
