```typescript
// Domain/ValueObjects/Money.ts
export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: string
  ) {}

  public static create(amount: number, currency: string): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure(new MoneyError("Amount must be positive"));
    }

    if (!currency || currency.trim().length === 0) {
      return Result.failure(new MoneyError("Currency must be provided"));
    }

    return Result.success(new Money(amount, currency));
  }

  public add(other: Money): Result<Money, MoneyError> {
    if (this._currency !== other._currency) {
      return Result.failure(new MoneyError("Currencies must match"));
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  public get amount(): number {
    return this._amount;
  }

  public get currency(): string {
    return this._currency;
  }

  public equals(other: Money): boolean {
    return this._amount === other._amount && this._currency === other._currency;
  }
}

// Domain/Errors/MoneyError.ts
export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

// Domain/Result.ts
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  public static success<T, E extends Error>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  public static failure<T, E extends Error>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: `Money` is immutable and has no identity
2. **Domain Validation**: 
   - Enforces positive amounts
   - Validates currency is provided
3. **Currency Safety**: 
   - `add` method checks currency match
   - Returns typed errors via `Result` pattern
4. **No External Dependencies**: 
   - No framework or infrastructure dependencies
   - Pure TypeScript with no external libraries
5. **Typed Errors**: 
   - `MoneyError` extends `Error` for proper error handling
   - `Result<T, E>` pattern for safe error propagation
6. **SOLID Compliance**:
   - Single Responsibility: `Money` handles only money-related logic
   - Open/Closed: Can be extended without modifying existing code
   - Liskov Substitution: `Result` can be used consistently
   - Interface Segregation: No unnecessary interfaces
   - Dependency Inversion: Dependencies are to abstractions (interfaces) not concretions

The `Result` pattern ensures that all operations that might fail return either a success with the result or a failure with an error, making error handling explicit and preventing silent failures.

```typescript
// Domain Layer

/**
 * Domain Event interface - represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  /**
   * Publishes a domain event
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>>;
}

// Application Layer

/**
 * Domain Error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventPublishingError";
  }
}

// Infrastructure Layer - Test Double Implementation

/**
 * In-Memory Event Publisher - Test Double implementation
 * Used for testing without external dependencies
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private events: IDomainEvent[] = [];
  private subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event to in-memory storage
   * @param event - The domain event to publish
   * @returns Success result
   */
  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      this.events.push(event);
      this.subscribers.forEach(subscriber => subscriber(event));
      return Result.success<void>(undefined);
    } catch (error) {
      return Result.failure<EventPublishingError>(
        new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`)
      );
    }
  }

  /**
   * Gets all published events
   * @returns Array of published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clears all published events
   */
  clearEvents(): void {
    this.events = [];
  }

  /**
   * Subscribe to events
   * @param subscriber - Function to be called when an event is published
   */
  subscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers.push(subscriber);
  }

  /**
   * Unsubscribe from events
   * @param subscriber - Function to remove from subscribers
   */
  unsubscribe(subscriber: (event: IDomainEvent) => void): void {
    const index = this.subscribers.indexOf(subscriber);
    if (index > -1) {
      this.subscribers.splice(index, 1);
    }
  }
}

// Result type implementation (used in the pattern)
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
```

Restructure this renewal job using Clean Architecture. Billing rules, Stripe and Sequelize are tangled together:

```typescript
cron.schedule('0 3 * * *', async () => {
  const due = await Subscription.findAll({
    where: { status: 'active', renewsAt: { [Op.lte]: new Date() } },
  });
  for (const sub of due) {
    try {
      await stripe.paymentIntents.create({
        amount: sub.priceCents, currency: 'usd', customer: sub.stripeCustomerId,
        payment_method: sub.defaultPaymentMethod, off_session: true, confirm: true,
      });
      const next = new Date(sub.renewsAt);
      next.setMonth(next.getMonth() + (sub.interval === 'yearly' ? 12 : 1));
      await sub.update({ renewsAt: next, failedAttempts: 0 });
    } catch (e) {
      const attempts = sub.failedAttempts + 1;
      await sub.update({ failedAttempts: attempts, status: attempts >= 3 ? 'past_due' : 'active' });
    }
  }
});
```

### Architectural Flaws in Original Code
1. **Renewal policy hidden in a cron callback:** the billing interval and the three-strike rule cannot be tested without Stripe and a database.
2. **Active Record models as domain:** `sub.update(...)` couples state changes to Sequelize.
3. **Exceptions as control flow:** any error, including a bug, is counted as a failed charge.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Subscription.ts`)
```typescript
export type BillingInterval = 'monthly' | 'yearly';
export type SubscriptionStatus = 'active' | 'past_due';

export class Subscription {
  static readonly MAX_FAILED_ATTEMPTS = 3;

  constructor(
    readonly id: string,
    readonly customerRef: string,
    readonly paymentMethodRef: string,
    readonly priceCents: number,
    readonly interval: BillingInterval,
    private renewal: Date,
    private failures: number,
    private state: SubscriptionStatus,
  ) {}

  get renewsAt(): Date { return this.renewal; }
  get failedAttempts(): number { return this.failures; }
  get status(): SubscriptionStatus { return this.state; }

  renewed(): void {
    const next = new Date(this.renewal);
    next.setMonth(next.getMonth() + (this.interval === 'yearly' ? 12 : 1));
    this.renewal = next;
    this.failures = 0;
  }

  chargeFailed(): void {
    this.failures += 1;
    if (this.failures >= Subscription.MAX_FAILED_ATTEMPTS) this.state = 'past_due';
  }
}
```

#### 2. Application Layer (`src/application/RenewDueSubscriptions.ts`)
```typescript
import { Result } from '../shared/Result';
import { Subscription } from '../domain/Subscription';

export type ChargeError = { kind: 'Declined'; reason: string };

export interface SubscriptionRepository {
  findDue(asOf: Date): Promise<Subscription[]>;
  save(subscription: Subscription): Promise<void>;
}

export interface PaymentProcessor {
  charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>>;
}

export class RenewDueSubscriptions {
  constructor(
    private readonly subscriptions: SubscriptionRepository,
    private readonly payments: PaymentProcessor,
    private readonly now: () => Date,
  ) {}

  async execute(): Promise<{ renewed: number; failed: number }> {
    let renewed = 0;
    let failed = 0;
    for (const sub of await this.subscriptions.findDue(this.now())) {
      const charge = await this.payments.charge(sub.customerRef, sub.paymentMethodRef, sub.priceCents);
      if (charge.success) { sub.renewed(); renewed++; } else { sub.chargeFailed(); failed++; }
      await this.subscriptions.save(sub);
    }
    return { renewed, failed };
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/StripePaymentProcessor.ts`)
```typescript
import Stripe from 'stripe';
import { Result } from '../shared/Result';
import { ChargeError, PaymentProcessor } from '../application/RenewDueSubscriptions';

function isCardDecline(error: unknown): error is { type: 'StripeCardError'; message: string } {
  return typeof error === 'object' && error !== null && (error as { type?: unknown }).type === 'StripeCardError';
}

export class StripePaymentProcessor implements PaymentProcessor {
  constructor(private readonly stripe: Stripe) {}

  async charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>> {
    try {
      await this.stripe.paymentIntents.create({
        amount: amountCents, currency: 'usd', customer: customerRef,
        payment_method: paymentMethodRef,
        off_session: true, confirm: true,
      });
      return Result.ok(undefined);
    } catch (error) {
      if (isCardDecline(error)) {
        return Result.fail({ kind: 'Declined', reason: error.message });
      }
      throw error; // infrastructure failures are not counted as declined charges
    }
  }
}
```
A `SequelizeSubscriptionRepository` maps rows to `Subscription` in `findDue` (`status: 'active'`, `renewsAt <= asOf`) and writes `renewsAt`, `failedAttempts` and `status` back in `save`.

