```typescript
// Domain/Errors/ValidationError.ts
export class ValidationError {
  constructor(public readonly message: string) {}
}

// Domain/ValueObjects/Email.ts
import { Result, ok, error } from '../Result';
import { ValidationError } from '../Errors/ValidationError';

export class Email {
  private constructor(public readonly value: string) {}

  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return error(new ValidationError('Email must be a non-empty string'));
    }

    // Check if email is non-empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return error(new ValidationError('Email cannot be empty'));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return error(new ValidationError('Email format is invalid'));
    }

    return ok(new Email(normalizedEmail));
  }

  equals(other: Email): boolean {
    return this.value === other.value;
  }

  toString(): string {
    return this.value;
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return { isSuccess: true, value };
}

export function error<E>(error: E): Result<never, E> {
  return { isSuccess: false, error };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: The `Email` class is immutable and represents a value with no identity
2. **Invariant Validation**:
   - Ensures email is a non-empty string
   - Validates email format using regex
   - Normalizes to lowercase
   - Trims whitespace
3. **Result Pattern**: Returns `Result<Email, ValidationError>` for safe error handling
4. **No External Dependencies**: The domain layer doesn't depend on any frameworks or infrastructure
5. **Typed Errors**: Uses `ValidationError` for specific error handling
6. **Strict Types**: No `any` types used; all types are explicitly defined
7. **Dependency Rule Compliance**: Domain layer is completely independent of external libraries

The `Email` value object enforces invariants through its factory method `create()` which validates all constraints before creating an instance. The validation includes:
- Non-empty string check
- Format validation using regex
- Lowercase normalization
- Whitespace trimming

The Result pattern ensures that validation failures are explicitly handled and cannot be ignored.

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    // Validate input
    if (!request.userId) {
      return error(new InvalidPasswordError('User ID is required'));
    }

    if (!request.currentPassword) {
      return error(new InvalidPasswordError('Current password is required'));
    }

    if (!request.newPassword) {
      return error(new InvalidPasswordError('New password is required'));
    }

    // Check if user exists
    const user = await this.userRepository.findById(request.userId);
    if (!user) {
      return error(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      request.currentPassword,
      user.passwordHash
    );

    if (!isPasswordValid) {
      return error(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      request.newPassword,
      user.passwordHash
    );

    if (isSamePassword) {
      return error(new InvalidPasswordError('New password cannot be the same as the current password'));
    }

    // Hash new password
    const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = Success<T> | Failure<E>;

interface Success<T> {
  isSuccess: true;
  value: T;
  error?: never;
}

interface Failure<E extends DomainError> {
  isSuccess: false;
  value?: never;
  error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error
  };
}
```

