// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be positive");
    this.name = "InvalidAmountError";
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Currencies must match for addition");
    this.name = "CurrencyMismatchError";
  }
}

export class MoneyValueObject {
  private constructor(private readonly _amount: number, private readonly _currency: string) {
    if (_amount < 0) {
      throw new InvalidAmountError();
    }
  }

  static create(amount: number, currency: string): Money {
    return new MoneyValueObject(amount, currency);
  }

  get amount(): number {
    return this._amount;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    if (this._currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    return new MoneyValueObject(
      this._amount + other.amount,
      this._currency
    );
  }

  equals(other: Money): boolean {
    return this._amount === other.amount && this._currency === other.currency;
  }
}
```

Critique this class against the SOLID principles and refactor it:

```typescript
class PriceCalculator {
  calculate(customerType: string, base: number): number {
    switch (customerType) {
      case 'regular': return base;
      case 'vip': return base * 0.8;
      case 'employee': return base * 0.5;
      default: throw new Error('Unknown customer type');
    }
  }
}
```

### SOLID Critique
- **OCP (violated):** every new customer type forces an edit to `calculate`, risking regressions in existing branches.
- **SRP (borderline):** the class knows every pricing policy, so it changes for each business decision.
- **Stringly-typed input:** `customerType: string` allows typos that only fail at runtime.

---

### Refactoring: Strategy per customer type
```typescript
export interface PricingStrategy {
  apply(base: number): number;
}

export class RegularPricing implements PricingStrategy {
  apply(base: number): number { return base; }
}

export class VipPricing implements PricingStrategy {
  apply(base: number): number { return base * 0.8; }
}

export class EmployeePricing implements PricingStrategy {
  apply(base: number): number { return base * 0.5; }
}

export class PriceCalculator {
  constructor(private readonly strategies: ReadonlyMap<string, PricingStrategy>) {}

  calculate(customerType: string, base: number): number {
    const strategy = this.strategies.get(customerType);
    if (!strategy) throw new Error('Unknown customer type');
    return strategy.apply(base);
  }
}
```

Adding a `student` discount now means adding one class and one map entry. `PriceCalculator` stays closed for modification (OCP), and each strategy can be tested in isolation.

This NestJS controller reserves warehouse stock but every rule sits next to TypeORM calls. Refactor it to Clean Architecture:

```typescript
@Controller('reservations')
export class ReservationController {
  constructor(
    @InjectRepository(StockItem) private stock: Repository<StockItem>,
    @InjectRepository(Reservation) private reservations: Repository<Reservation>,
  ) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    if (!Number.isInteger(body.quantity) || body.quantity <= 0) {
      throw new BadRequestException('Quantity must be a positive integer');
    }
    const item = await this.stock.findOne({ where: { sku: body.sku } });
    if (!item) throw new NotFoundException('Unknown SKU');
    const available = item.onHand - item.reserved;
    if (available < body.quantity) {
      throw new ConflictException(`Only ${available} units available`);
    }
    item.reserved += body.quantity;
    await this.stock.save(item);
    return this.reservations.save({ sku: body.sku, quantity: body.quantity, createdAt: new Date() });
  }
}
```

### Architectural Flaws in Original Code
1. **Framework exceptions as business errors:** `BadRequestException` and `ConflictException` tie the reservation rules to NestJS.
2. **ORM entities as domain model:** the availability calculation mutates a TypeORM row in the controller.
3. **No atomic boundary:** the stock update and the reservation insert are two unrelated saves.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/StockItem.ts`)
```typescript
import { Result } from '../shared/Result';

export type ReservationError =
  | { kind: 'InvalidQuantity' }
  | { kind: 'UnknownSku'; sku: string }
  | { kind: 'InsufficientStock'; available: number };

export class StockItem {
  constructor(
    readonly sku: string,
    readonly onHand: number,
    private reservedUnits: number,
  ) {}

  get reserved(): number {
    return this.reservedUnits;
  }

  get available(): number {
    return this.onHand - this.reservedUnits;
  }

  reserve(quantity: number): Result<void, ReservationError> {
    if (!Number.isInteger(quantity) || quantity <= 0) {
      return Result.fail({ kind: 'InvalidQuantity' });
    }
    if (this.available < quantity) {
      return Result.fail({ kind: 'InsufficientStock', available: this.available });
    }
    this.reservedUnits += quantity;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/ReserveStock.ts`)
```typescript
import { Result } from '../shared/Result';
import { ReservationError, StockItem } from '../domain/StockItem';

export interface StockReservation {
  readonly sku: string;
  readonly quantity: number;
  readonly createdAt: Date;
}

export interface StockStore {
  findBySku(sku: string): Promise<StockItem | null>;
  /** Persists the item and the reservation in one transaction. */
  commit(item: StockItem, reservation: StockReservation): Promise<void>;
}

export class ReserveStock {
  constructor(private readonly store: StockStore, private readonly now: () => Date) {}

  async execute(sku: string, quantity: number): Promise<Result<StockReservation, ReservationError>> {
    const item = await this.store.findBySku(sku);
    if (!item) return Result.fail({ kind: 'UnknownSku', sku });

    const reserved = item.reserve(quantity);
    if (!reserved.success) return reserved;

    const reservation: StockReservation = { sku, quantity, createdAt: this.now() };
    await this.store.commit(item, reservation);
    return Result.ok(reservation);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/TypeOrmStockStore.ts`)
```typescript
import { DataSource } from 'typeorm';
import { StockItem } from '../domain/StockItem';
import { StockReservation, StockStore } from '../application/ReserveStock';
import { StockItemRow, ReservationRow } from './rows';

export class TypeOrmStockStore implements StockStore {
  constructor(private readonly db: DataSource) {}

  async findBySku(sku: string): Promise<StockItem | null> {
    const row = await this.db.getRepository(StockItemRow).findOne({ where: { sku } });
    return row ? new StockItem(row.sku, row.onHand, row.reserved) : null;
  }

  async commit(item: StockItem, reservation: StockReservation): Promise<void> {
    await this.db.transaction(async (tx) => {
      await tx.getRepository(StockItemRow).update({ sku: item.sku }, { reserved: item.reserved });
      await tx.getRepository(ReservationRow).insert({ ...reservation });
    });
  }
}
```

#### 4. Presentation Layer (NestJS controller)
```typescript
import { BadRequestException, Body, ConflictException, Controller, NotFoundException, Post } from '@nestjs/common';
import { ReserveStock } from '../application/ReserveStock';

@Controller('reservations')
export class ReservationController {
  constructor(private readonly reserveStock: ReserveStock) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    const result = await this.reserveStock.execute(body.sku, body.quantity);
    if (result.success) return result.data;
    const error = result.error;
    switch (error.kind) {
      case 'InvalidQuantity':
        throw new BadRequestException('Quantity must be a positive integer');
      case 'UnknownSku':
        throw new NotFoundException('Unknown SKU');
      case 'InsufficientStock':
        throw new ConflictException(`Only ${error.available} units available`);
    }
  }
}
```

NestJS exceptions now live only at the edge; the domain reports failures as typed values.

Critique this interface with the Interface Segregation Principle and SOLID, then refactor:

```typescript
interface Worker {
  work(): void;
  eat(): void;
  sleep(): void;
}
class Human implements Worker {
  work() { /* ... */ } eat() { /* ... */ } sleep() { /* ... */ }
}
class Robot implements Worker {
  work() { /* ... */ }
  eat() { throw new Error('Robots do not eat'); }
  sleep() { throw new Error('Robots do not sleep'); }
}
```

### SOLID Critique
- **ISP (violated):** `Robot` is forced to depend on `eat` and `sleep`, which it cannot implement.
- **LSP (violated as a consequence):** a `Robot` passed where a `Worker` is expected throws on `eat()`.
- **Fat interface:** three unrelated responsibilities (production, nutrition, rest) share one contract.

---

### Refactoring: role interfaces
```typescript
export interface Workable { work(): void }
export interface Feedable { eat(): void }
export interface Restable { sleep(): void }

export class Human implements Workable, Feedable, Restable {
  work(): void { /* ... */ }
  eat(): void { /* ... */ }
  sleep(): void { /* ... */ }
}

export class Robot implements Workable {
  work(): void { /* ... */ }
}

export function runShift(workers: Workable[]): void {
  workers.forEach((worker) => worker.work());
}

export function lunchBreak(people: Feedable[]): void {
  people.forEach((person) => person.eat());
}
```

Each client depends only on the role it uses. `Robot` no longer carries dead methods and no substitution can throw.

```typescript
// Domain Layer

/**
 * Interface representing a domain event
 */
export interface IDomainEvent {
  readonly id: string;
  readonly occurredOn: Date;
  readonly eventType: string;
}

/**
 * Interface for event publisher port
 */
export interface IEventPublisher {
  publish(event: IDomainEvent): Promise<void>;
}

// Application Layer

import { IEventPublisher } from '../domain/ports/IEventPublisher';

/**
 * Application service that uses the event publisher
 */
export class EventHandlingService {
  constructor(private readonly eventPublisher: IEventPublisher) {}

  async handleDomainEvent(event: IDomainEvent): Promise<void> {
    await this.eventPublisher.publish(event);
  }
}

// Infrastructure Layer - Test Double Implementation

import { IEventPublisher } from '../../domain/ports/IEventPublisher';

/**
 * In-memory test double implementation of IEventPublisher
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private events: IDomainEvent[] = [];

  async publish(event: IDomainEvent): Promise<void> {
    this.events.push(event);
  }

  /**
   * Get all published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clear all published events
   */
  clear(): void {
    this.events = [];
  }

  /**
   * Get count of published events
   */
  getPublishedEventsCount(): number {
    return this.events.length;
  }
}
```

This implementation follows Clean Architecture principles:

1. **Domain Layer**:
   - Defines `IDomainEvent` interface with required properties
   - Defines `IEventPublisher` port interface
   - No dependencies on external libraries or frameworks

2. **Application Layer**:
   - Uses the `IEventPublisher` port as a dependency
   - Contains application logic that depends only on domain concepts

3. **Infrastructure Layer**:
   - Provides `InMemoryEventPublisher` test double implementation
   - Implements the `IEventPublisher` interface
   - Used exclusively for testing scenarios

The `InMemoryEventPublisher` is a test double that:
- Stores events in memory
- Provides methods to inspect published events
- Supports clearing events for test isolation
- Maintains the same interface as production implementations

All dependencies flow inward (domain → application → infrastructure) as required by the Dependency Rule.

Critique this code using the Liskov Substitution Principle and SOLID, then fix it:

```typescript
class Bird {
  fly(): string { return 'flying'; }
}
class Penguin extends Bird {
  fly(): string { throw new Error('Penguins cannot fly'); }
}
function launch(birds: Bird[]) {
  return birds.map(b => b.fly());
}
```

### SOLID Critique
- **LSP (violated):** `Penguin` cannot stand in for `Bird`. `launch([new Penguin()])` throws, so callers must know the concrete subtype.
- **Root cause:** the base type promises a capability (`fly`) that not every bird has. The hierarchy models taxonomy, not behavior.
- **ISP angle:** `Bird` forces a `fly` contract on types that cannot honor it.

---

### Refactoring: split capabilities
```typescript
export interface Bird {
  readonly name: string;
}

export interface FlyingBird extends Bird {
  fly(): string;
}

export class Sparrow implements FlyingBird {
  readonly name = 'sparrow';
  fly(): string { return 'flying'; }
}

export class Penguin implements Bird {
  readonly name = 'penguin';
}

export function launch(birds: FlyingBird[]): string[] {
  return birds.map((bird) => bird.fly());
}
```

`launch` now only accepts types that can fly, so the invalid call `launch([new Penguin()])` fails at compile time instead of at runtime. Every `FlyingBird` is fully substitutable.

Refactor this React component to separate business logic from UI and data fetching:

```tsx
function Cart({ userId }: { userId: string }) {
  const [items, setItems] = useState<any[]>([]);
  useEffect(() => {
    fetch('/api/cart/' + userId).then(r => r.json()).then(setItems);
  }, [userId]);
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const discount = subtotal > 100 ? subtotal * 0.1 : 0;
  return <div>{items.map(i => <p key={i.id}>{i.name}</p>)}<b>{subtotal - discount}</b></div>;
}
```

### Architectural Flaws in Original Code
1. **Pricing rule inside a component:** the 10% discount over 100 cannot be tested without rendering.
2. **Direct `fetch` in the view:** the component knows the URL scheme and JSON shape.
3. **`any[]`:** the cart shape is untyped, so mistakes surface only at runtime.

---

### Clean Architecture Refactoring

#### 1. Domain (`src/domain/Cart.ts`)
```typescript
export interface CartItem { readonly id: string; readonly name: string; readonly price: number; readonly qty: number }

export class Cart {
  constructor(private readonly items: readonly CartItem[]) {}

  get lines(): readonly CartItem[] { return this.items; }

  subtotal(): number {
    return this.items.reduce((sum, item) => sum + item.price * item.qty, 0);
  }

  discount(): number {
    const subtotal = this.subtotal();
    return subtotal > 100 ? subtotal * 0.1 : 0;
  }

  total(): number { return this.subtotal() - this.discount(); }
}
```

#### 2. Application (`src/application/LoadCartUseCase.ts`)
```typescript
import { Cart, CartItem } from '../domain/Cart';

export interface ICartSource { fetchItems(userId: string): Promise<CartItem[]> }

export class LoadCartUseCase {
  constructor(private readonly source: ICartSource) {}

  async execute(userId: string): Promise<Cart> {
    return new Cart(await this.source.fetchItems(userId));
  }
}
```

#### 3. Infrastructure (`src/infrastructure/HttpCartSource.ts`)
```typescript
export class HttpCartSource implements ICartSource {
  async fetchItems(userId: string): Promise<CartItem[]> {
    const response = await fetch(`/api/cart/${userId}`);
    if (!response.ok) throw new Error(`Cart request failed: ${response.status}`);
    return (await response.json()) as CartItem[];
  }
}
```

#### 4. Presentation (hook + dumb component)
```tsx
function useCart(userId: string, loadCart: LoadCartUseCase) {
  const [cart, setCart] = useState<Cart | null>(null);
  useEffect(() => { loadCart.execute(userId).then(setCart); }, [userId, loadCart]);
  return cart;
}

function CartView({ cart }: { cart: Cart }) {
  return (
    <div>
      {cart.lines.map((i) => <p key={i.id}>{i.name}</p>)}
