Critique this logger with SOLID and improve it:

```typescript
class Logger {
  log(level: string, msg: string) {
    const line = `[${new Date().toISOString()}] ${level}: ${msg}`;
    if (process.env.LOG_TARGET === 'file') fs.appendFileSync('app.log', line + '\n');
    else console.log(line);
  }
}
```

### SOLID Critique
- **OCP (violated):** a new target (HTTP collector, syslog) means editing `log`.
- **SRP (violated):** formatting, clock access, configuration lookup and output all live in one method.
- **DIP (violated):** it reads `process.env` and calls `fs` and `console` directly, and the clock is hidden.

---

### Refactoring: formatter, sinks and clock as collaborators
```typescript
export interface LogSink { write(line: string): void }
export interface Clock { now(): Date }

export class ConsoleSink implements LogSink {
  write(line: string): void { console.log(line); }
}

export class FileSink implements LogSink {
  constructor(private readonly path: string, private readonly append: (path: string, text: string) => void) {}
  write(line: string): void { this.append(this.path, line + '\n'); }
}

export class Logger {
  constructor(private readonly sink: LogSink, private readonly clock: Clock) {}

  log(level: 'info' | 'warn' | 'error', message: string): void {
    this.sink.write(`[${this.clock.now().toISOString()}] ${level}: ${message}`);
  }
}
```

The composition root picks the sink from configuration once. `Logger` is closed for modification, deterministic under a fake `Clock`, and typed levels remove the free-form `string`.

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    try {
      // Validate input
      if (!request.userId) {
        return error(new InvalidPasswordError('User ID is required'));
      }

      if (!request.currentPassword) {
        return error(new InvalidPasswordError('Current password is required'));
      }

      if (!request.newPassword) {
        return error(new InvalidPasswordError('New password is required'));
      }

      // Fetch user
      const user = await this.userRepository.findById(request.userId);
      if (!user) {
        return error(new PasswordMismatchError('User not found'));
      }

      // Verify current password
      const isPasswordValid = await this.passwordHasher.compare(
        request.currentPassword,
        user.passwordHash
      );

      if (!isPasswordValid) {
        return error(new PasswordMismatchError('Current password is incorrect'));
      }

      // Business rule: new password cannot equal old password
      const isSamePassword = await this.passwordHasher.compare(
        request.newPassword,
        user.passwordHash
      );

      if (isSamePassword) {
        return error(new InvalidPasswordError('New password cannot be the same as the current password'));
      }

      // Hash new password
      const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

      // Update user with new password hash
      const updatedUser: User = {
        ...user,
        passwordHash: newPasswordHash
      };

      await this.userRepository.update(updatedUser);

      return ok(undefined);
    } catch (err) {
      if (err instanceof DomainError) {
        return error(err);
      }
      return error(new InvalidPasswordError('Failed to change password'));
    }
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = {
  isSuccess: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error
  };
}
```

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { Request, Response } from 'express';
import { getRepository } from 'typeorm';
import { Order } from '../entities/Order';
import { ReturnRequest } from '../entities/ReturnRequest';
import { shippo } from '../shippo';

export async function createReturn(req: Request, res: Response) {
  const order = await getRepository(Order).findOne(req.params.orderId, { relations: ['lines'] });
  if (!order || order.customerId !== req.user.id) return res.sendStatus(404);
  const line = order.lines.find((l) => l.id === req.body.lineId);
  if (!line) return res.status(400).json({ error: 'Unknown line' });
  const days = (Date.now() - order.deliveredAt.getTime()) / 86400000;
  const window = line.category === 'electronics' ? 15 : 30;
  if (days > window) return res.status(422).json({ error: `Return window of ${window} days has passed` });
  if (line.finalSale) return res.status(422).json({ error: 'Final sale items cannot be returned' });
  const label = await shippo.transaction.create({ rate: process.env.RETURN_RATE_ID, label_file_type: 'PDF' });
  const ret = await getRepository(ReturnRequest).save({
    orderId: order.id, lineId: line.id, labelUrl: label.label_url, refundCents: line.priceCents * line.qty,
  });
  res.status(201).json(ret);
}

```

### Architectural Flaws in Original Code
1. **Return policy in a controller:** the 15/30-day windows and the final-sale rule depend on Express and TypeORM.
2. **Global repository access:** `getRepository(...)` is a hidden dependency that cannot be swapped.
3. **Carrier SDK and environment in the flow:** the shipping label is created inline with `process.env`.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/returns.ts`)
```typescript
import { Result } from '../shared/Result';

export interface PurchasedLine {
  readonly id: string;
  readonly category: string;
  readonly finalSale: boolean;
  readonly priceCents: number;
  readonly qty: number;
}

export interface DeliveredOrder {
  readonly id: string;
  readonly customerId: string;
  readonly deliveredAt: Date;
  readonly lines: readonly PurchasedLine[];
}

export type ReturnError =
  | { kind: 'OrderNotFound' }
  | { kind: 'UnknownLine' }
  | { kind: 'WindowClosed'; windowDays: number }
  | { kind: 'FinalSale' };

export function returnWindowDays(line: PurchasedLine): number {
  return line.category === 'electronics' ? 15 : 30;
}

export function checkReturnable(order: DeliveredOrder, lineId: string, now: Date): Result<PurchasedLine, ReturnError> {
  const line = order.lines.find((l) => l.id === lineId);
  if (!line) return Result.fail({ kind: 'UnknownLine' });
  const days = (now.getTime() - order.deliveredAt.getTime()) / 86_400_000;
  const windowDays = returnWindowDays(line);
  if (days > windowDays) return Result.fail({ kind: 'WindowClosed', windowDays });
  if (line.finalSale) return Result.fail({ kind: 'FinalSale' });
  return Result.ok(line);
}
```

#### 2. Application Layer (`src/application/CreateReturn.ts`)
```typescript
import { Result } from '../shared/Result';
import { DeliveredOrder, ReturnError, checkReturnable } from '../domain/returns';

export interface ReturnRecord {
  readonly orderId: string;
  readonly lineId: string;
  readonly labelUrl: string;
  readonly refundCents: number;
}

export interface OrderReader { findWithLines(orderId: string): Promise<DeliveredOrder | null>; }
export interface ReturnLabels { create(): Promise<string>; }
export interface ReturnRepository { save(record: ReturnRecord): Promise<ReturnRecord>; }

export class CreateReturn {
  constructor(
    private readonly orders: OrderReader,
    private readonly labels: ReturnLabels,
    private readonly returns: ReturnRepository,
    private readonly now: () => Date,
  ) {}

  async execute(customerId: string, orderId: string, lineId: string): Promise<Result<ReturnRecord, ReturnError>> {
    const order = await this.orders.findWithLines(orderId);
    if (!order || order.customerId !== customerId) return Result.fail({ kind: 'OrderNotFound' });

    const line = checkReturnable(order, lineId, this.now());
    if (!line.success) return line;

    const labelUrl = await this.labels.create();
    const saved = await this.returns.save({
      orderId, lineId, labelUrl, refundCents: line.data.priceCents * line.data.qty,
    });
    return Result.ok(saved);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/ShippoReturnLabels.ts`)
```typescript
import { ReturnLabels } from '../application/CreateReturn';

interface ShippoClient {
  transaction: { create(input: { rate: string; label_file_type: 'PDF' }): Promise<{ label_url: string }> };
}

export class ShippoReturnLabels implements ReturnLabels {
  constructor(private readonly shippo: ShippoClient, private readonly rateId: string) {}

  async create(): Promise<string> {
    const label = await this.shippo.transaction.create({ rate: this.rateId, label_file_type: 'PDF' });
    return label.label_url;
  }
}
```
`TypeOrmOrderReader` and `TypeOrmReturnRepository` receive a `DataSource` and map the existing `Order` and `ReturnRequest` rows.

#### 4. Presentation Layer (`src/http/returnsController.ts`)
```typescript
import { Request, Response } from 'express';

function toHttp(error: ReturnError): [number, string | null] {
  switch (error.kind) {
    case 'OrderNotFound': return [404, null];
    case 'UnknownLine': return [400, 'Unknown line'];
    case 'WindowClosed': return [422, `Return window of ${error.windowDays} days has passed`];
    case 'FinalSale': return [422, 'Final sale items cannot be returned'];
  }
}

export const createReturnHandler = (createReturn: CreateReturn) => async (req: Request, res: Response) => {
  const result = await createReturn.execute(req.user.id, req.params.orderId, req.body.lineId);
  if (result.success) return res.status(201).json(result.data);
  const [status, message] = toHttp(result.error);
  return message ? res.status(status).json({ error: message }) : res.sendStatus(status);
};
```

Refactor this Lambda-style function where pricing, tax rules and DynamoDB access share one body:

```typescript
exports.handler = async (event) => {
  const cart = JSON.parse(event.body);
  const net = cart.lines.reduce((s, l) => s + l.unit * l.qty, 0);
  const tax = cart.country === 'DE' ? net * 0.19 : cart.country === 'FR' ? net * 0.2 : 0;
  await dynamo.put({ TableName: 'quotes', Item: { id: cart.id, net, tax } }).promise();
