In this Angular service the seat selection rules are mixed with HttpClient calls. Apply Clean Architecture so the rules have no Angular dependency:

```typescript
@Injectable({ providedIn: 'root' })
export class SeatService {
  constructor(private http: HttpClient) {}

  async select(flightId: string, seat: string, passenger: { age: number; tier: string }) {
    const map = await firstValueFrom(this.http.get<any>(`/api/flights/${flightId}/seats`));
    const s = map.seats.find((x: any) => x.code === seat);
    if (!s || s.taken) throw new Error('Seat not available');
    if (s.exitRow && passenger.age < 15) throw new Error('Exit row requires age 15+');
    let fee = 0;
    if (s.extraLegroom) fee = passenger.tier === 'gold' ? 0 : 35;
    else if (s.row <= 5) fee = passenger.tier === 'gold' ? 0 : 20;
    await firstValueFrom(this.http.post(`/api/flights/${flightId}/seats/${seat}`, { fee }));
    return fee;
  }
}
```

### Architectural Flaws in Original Code
1. **Business rules in a framework service:** exit-row age limits and seat fees depend on `@Injectable` and `HttpClient`.
2. **`any` everywhere:** the seat map is untyped, so a renamed field breaks silently.
3. **Errors as thrown strings:** callers cannot tell "seat taken" from "age restriction" without parsing messages.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/seating.ts`)
```typescript
import { Result } from '../shared/Result';

export type LoyaltyTier = 'standard' | 'silver' | 'gold';

export interface Seat {
  readonly code: string;
  readonly row: number;
  readonly taken: boolean;
  readonly exitRow: boolean;
  readonly extraLegroom: boolean;
}

export interface Passenger {
  readonly age: number;
  readonly tier: LoyaltyTier;
}

export type SeatError =
  | { kind: 'SeatUnavailable'; seat: string }
  | { kind: 'ExitRowAgeRestriction'; minimumAge: number };

export const EXIT_ROW_MIN_AGE = 15;

export function seatFee(seat: Seat, passenger: Passenger): Result<number, SeatError> {
  if (seat.taken) return Result.fail({ kind: 'SeatUnavailable', seat: seat.code });
  if (seat.exitRow && passenger.age < EXIT_ROW_MIN_AGE) {
    return Result.fail({ kind: 'ExitRowAgeRestriction', minimumAge: EXIT_ROW_MIN_AGE });
  }
  if (passenger.tier === 'gold') return Result.ok(0);
  if (seat.extraLegroom) return Result.ok(35);
  if (seat.row <= 5) return Result.ok(20);
  return Result.ok(0);
}
```

#### 2. Application Layer (`src/application/SelectSeat.ts`)
```typescript
import { Result } from '../shared/Result';
import { Passenger, Seat, SeatError, seatFee } from '../domain/seating';

export interface SeatMapSource {
  seats(flightId: string): Promise<Seat[]>;
  assign(flightId: string, seatCode: string, fee: number): Promise<void>;
}

export class SelectSeat {
  constructor(private readonly seatMap: SeatMapSource) {}

  async execute(flightId: string, seatCode: string, passenger: Passenger): Promise<Result<number, SeatError>> {
    const seat = (await this.seatMap.seats(flightId)).find((s) => s.code === seatCode);
    if (!seat) return Result.fail({ kind: 'SeatUnavailable', seat: seatCode });

    const fee = seatFee(seat, passenger);
    if (!fee.success) return fee;

    await this.seatMap.assign(flightId, seatCode, fee.data);
    return fee;
  }
}
```

#### 3. Infrastructure Layer (`src/app/infrastructure/HttpSeatMapSource.ts`)
Angular stays here: the class implements the application interface with `HttpClient`.
```typescript
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { Seat } from '../../domain/seating';
import { SeatMapSource } from '../../application/SelectSeat';

interface SeatMapResponse { seats: Seat[]; }

@Injectable({ providedIn: 'root' })
export class HttpSeatMapSource implements SeatMapSource {
  constructor(private readonly http: HttpClient) {}

  async seats(flightId: string): Promise<Seat[]> {
    const map = await firstValueFrom(this.http.get<SeatMapResponse>(`/api/flights/${flightId}/seats`));
    return map.seats;
  }

  async assign(flightId: string, seatCode: string, fee: number): Promise<void> {
    await firstValueFrom(this.http.post(`/api/flights/${flightId}/seats/${seatCode}`, { fee }));
  }
}
```

#### 4. Presentation Layer (component)
```typescript
@Component({ selector: 'app-seat-picker', templateUrl: './seat-picker.component.html' })
export class SeatPickerComponent {
  message = '';
  private readonly selectSeat: SelectSeat;

  constructor(seatMap: HttpSeatMapSource) {
    this.selectSeat = new SelectSeat(seatMap);
  }

