    const result = await this.selectSeat.execute(flightId, seatCode, passenger);
    if (result.success) {
      this.message = result.data === 0 ? 'Seat confirmed' : `Seat confirmed, fee $${result.data}`;
    } else if (result.error.kind === 'ExitRowAgeRestriction') {
      this.message = `Exit row requires age ${result.error.minimumAge}+`;
    } else {
      this.message = 'Seat not available';
    }
  }
}
