Refactor this Next.js API handler that validates, queries MongoDB and formats the response in one function:

```typescript
async function handler(req, res) {
  const { sku, qty } = req.body;
  if (!sku || qty < 1) return res.status(400).end();
  const item = await mongo.collection('stock').findOne({ sku });
  if (!item || item.available < qty) return res.status(409).json({ error: 'Out of stock' });
  await mongo.collection('stock').updateOne({ sku }, { $inc: { available: -qty } });
  res.json({ reserved: qty, left: item.available - qty });
}
```

### Architectural Flaws in Original Code
1. **Stock rule in the handler:** the "enough units available" decision is core business logic.
2. **Driver coupling:** MongoDB calls are made directly from the HTTP layer.
3. **Race condition:** read-then-update lets two requests reserve the same units. The repository must make the decrement atomic.

---

### Clean Architecture Refactoring

#### 1. Domain (`src/domain/StockItem.ts`)
```typescript
export class StockItem {
  constructor(public readonly sku: string, public readonly available: number) {}

  canReserve(qty: number): boolean {
    return Number.isInteger(qty) && qty >= 1 && this.available >= qty;
  }
}
```

#### 2. Application (`src/application/ReserveStockUseCase.ts`)
```typescript
import { StockItem } from '../domain/StockItem';

export interface IStockRepository {
  find(sku: string): Promise<StockItem | null>;
  /** Atomically decrements; returns false when the stock changed underneath. */
  tryDecrement(sku: string, qty: number): Promise<boolean>;
}

export class ReserveStockUseCase {
  constructor(private readonly stock: IStockRepository) {}

  async execute(sku: string, qty: number): Promise<{ reserved: number; left: number }> {
    const item = await this.stock.find(sku);
    if (!item || !item.canReserve(qty)) throw new Error('Out of stock');
    if (!(await this.stock.tryDecrement(sku, qty))) throw new Error('Out of stock');
    return { reserved: qty, left: item.available - qty };
  }
}
```

#### 3. Infrastructure (atomic decrement) and controller
```typescript
/** The only part of the MongoDB collection API this adapter needs. */
interface StockCollection {
  findOne(filter: { sku: string }): Promise<{ sku: string; available: number } | null>;
  updateOne(
    filter: { sku: string; available: { $gte: number } },
    update: { $inc: { available: number } },
  ): Promise<{ modifiedCount: number }>;
}

class MongoStockRepository implements IStockRepository {
  constructor(private readonly collection: StockCollection) {}

  async find(sku: string): Promise<StockItem | null> {
    const doc = await this.collection.findOne({ sku });
    return doc ? new StockItem(doc.sku, doc.available) : null;
  }

  async tryDecrement(sku: string, qty: number): Promise<boolean> {
    const result = await this.collection.updateOne(
      { sku, available: { $gte: qty } },
      { $inc: { available: -qty } },
    );
    return result.modifiedCount === 1;
  }
}

interface ApiRequest { body: { sku: string; qty: number } }
interface ApiResponse {
  json(body: unknown): void;
  status(code: number): ApiResponse;
}

async function handler(req: ApiRequest, res: ApiResponse) {
  try {
    res.json(await reserveStock.execute(req.body.sku, req.body.qty));
  } catch (error) {
    res.status(409).json({ error: (error as Error).message });
  }
}
```

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { Injectable, BadRequestException } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Quote } from './quote.schema';

@Injectable()
export class QuoteService {
  constructor(@InjectModel(Quote.name) private quotes: Model<Quote>, private http: HttpService) {}

  async quote(dto: { driverAge: number; licenseYears: number; vehicleValue: number; zip: string }) {
    if (dto.driverAge < 18) throw new BadRequestException('Driver must be an adult');
    const { data } = await this.http.get(`https://risk.internal/zip/${dto.zip}`).toPromise();
    let premium = dto.vehicleValue * 0.035;
    if (dto.driverAge < 25) premium *= 1.6;
    if (dto.licenseYears < 2) premium *= 1.3;
    premium *= data.riskFactor;
    premium = Math.max(300, Math.round(premium));
    const doc = await this.quotes.create({ ...dto, premium, validUntil: new Date(Date.now() + 30 * 86400000) });
    return { id: doc.id, premium, validUntil: doc.validUntil };
  }
}

```

### Architectural Flaws in Original Code
1. **Underwriting rules in a NestJS service:** the base rate, young-driver and new-licence loadings and the 300 minimum premium are tied to `@Injectable`, Mongoose and `HttpService`.
2. **Deprecated, untyped HTTP call:** `.toPromise()` returns `data` with no shape check, and `firstValueFrom` is imported but unused.
3. **Framework exception for a business rule:** `BadRequestException` is thrown from the core logic.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/premium.ts`)
```typescript
import { Result } from '../shared/Result';

export interface DriverProfile {
  readonly driverAge: number;
  readonly licenseYears: number;
  readonly vehicleValue: number;
}

export type QuoteError = { kind: 'UnderageDriver' };

export const RATING = {
  baseRate: 0.035,
  youngDriverAge: 25,
  youngDriverLoading: 1.6,
  newLicenceYears: 2,
  newLicenceLoading: 1.3,
  minimumPremium: 300,
  validityDays: 30,
} as const;

export function checkEligibility(driver: DriverProfile): Result<DriverProfile, QuoteError> {
  return driver.driverAge < 18 ? Result.fail({ kind: 'UnderageDriver' }) : Result.ok(driver);
}

export function annualPremium(driver: DriverProfile, zipRiskFactor: number): number {
  let premium = driver.vehicleValue * RATING.baseRate;
  if (driver.driverAge < RATING.youngDriverAge) premium *= RATING.youngDriverLoading;
  if (driver.licenseYears < RATING.newLicenceYears) premium *= RATING.newLicenceLoading;
  premium *= zipRiskFactor;
  return Math.max(RATING.minimumPremium, Math.round(premium));
}
```

#### 2. Application Layer (`src/application/QuotePremium.ts`)
```typescript
import { Result } from '../shared/Result';
import { DriverProfile, QuoteError, RATING, annualPremium, checkEligibility } from '../domain/premium';

export interface IssuedQuote { readonly id: string; readonly premium: number; readonly validUntil: Date; }

export interface RiskByZip { factorFor(zip: string): Promise<number>; }
export interface QuoteRepository {
  save(input: DriverProfile & { zip: string; premium: number; validUntil: Date }): Promise<string>;
}

export class QuotePremium {
  constructor(private readonly risk: RiskByZip, private readonly quotes: QuoteRepository, private readonly now: () => Date) {}

  async execute(input: DriverProfile & { zip: string }): Promise<Result<IssuedQuote, QuoteError>> {
    const eligible = checkEligibility(input);
    if (!eligible.success) return eligible;
    const premium = annualPremium(input, await this.risk.factorFor(input.zip));
    const validUntil = new Date(this.now().getTime() + RATING.validityDays * 86_400_000);
    const id = await this.quotes.save({ ...input, premium, validUntil });
    return Result.ok({ id, premium, validUntil });
  }
}
```
The age check runs before the risk lookup, as before, so an underage request makes no remote call.

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
