// Domain/ValueObjects/Money.ts

export interface Currency {
  readonly code: string;
  readonly symbol: string;
  readonly decimalPlaces: number;
}

export interface MoneyError {
  readonly type: 'InvalidAmount' | 'CurrencyMismatch' | 'InvalidCurrency';
  readonly message: string;
}

export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: Currency
  ) {}

  get amount(): number {
    return this._amount;
  }

  get currency(): Currency {
    return this._currency;
  }

  /**
   * Creates a new Money instance with validation
   */
  static create(amount: number, currency: Currency): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure({
        type: 'InvalidAmount',
        message: 'Amount must be positive'
      });
    }

    if (!currency || !currency.code) {
      return Result.failure({
        type: 'InvalidCurrency',
        message: 'Invalid currency provided'
      });
    }

    return Result.success(new Money(amount, currency));
  }

  /**
   * Adds two Money instances with currency validation
   */
  add(other: Money): Result<Money, MoneyError> {
    if (this._currency.code !== other._currency.code) {
      return Result.failure({
        type: 'CurrencyMismatch',
        message: `Cannot add money in different currencies: ${this._currency.code} and ${other._currency.code}`
      });
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  /**
   * Checks if two Money instances are equal
   */
  equals(other: Money): boolean {
    return (
      this._amount === other._amount &&
      this._currency.code === other._currency.code
    );
  }

  /**
   * Returns a string representation of the Money instance
   */
  toString(): string {
    return `${this._currency.symbol}${this._amount.toFixed(this._currency.decimalPlaces)}`;
  }
}

// Result type for error handling
export class Result<T, E> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T, E>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  static failure<T, E>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }

  map<U>(fn: (value: T) => U): Result<U, E> {
    if (this.isSuccess) {
      return Result.success(fn(this.value!));
    }
    return Result.failure(this.error!);
  }

  flatMap<U>(fn: (value: T) => Result<U, E>): Result<U, E> {
    if (this.isSuccess) {
      return fn(this.value!);
    }
    return Result.failure(this.error!);
  }
}
```

Refactor this Vue 3 composable for event RSVPs. Capacity and plus-one rules are mixed with Firestore calls:

```typescript
export function useRsvp(eventId: string) {
  const error = ref<string | null>(null);

  async function rsvp(userId: string, guests: number) {
    error.value = null;
    const eventRef = doc(db, 'events', eventId);
    await runTransaction(db, async (tx) => {
      const snap = await tx.get(eventRef);
      const ev = snap.data()!;
      if (ev.rsvpClosesAt.toDate() < new Date()) { error.value = 'RSVP closed'; return; }
      if (guests > ev.maxGuestsPerRsvp) { error.value = `Max ${ev.maxGuestsPerRsvp} guests`; return; }
      const seats = 1 + guests;
      if (ev.attending + seats > ev.capacity) {
        tx.set(doc(db, 'events', eventId, 'waitlist', userId), { guests, at: serverTimestamp() });
        error.value = 'Event full, you are on the waitlist';
        return;
      }
      tx.update(eventRef, { attending: ev.attending + seats });
      tx.set(doc(db, 'events', eventId, 'rsvps', userId), { guests });
    });
  }

  return { rsvp, error };
}
```

### Architectural Flaws in Original Code
1. **Event rules inside a UI composable:** closing time, guest limit and capacity are only testable with Vue and Firestore.
2. **Business outcome reported through a ref:** "waitlisted" is a valid outcome, but it is stored as an error string.
3. **Non-null assertion on the snapshot:** a deleted event crashes the transaction.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/rsvp.ts`)
```typescript
import { Result } from '../shared/Result';

export interface EventCapacity {
  readonly capacity: number;
  readonly attending: number;
  readonly maxGuestsPerRsvp: number;
  readonly rsvpClosesAt: Date;
}

export type RsvpOutcome = { kind: 'Confirmed'; seats: number } | { kind: 'Waitlisted' };
export type RsvpError = { kind: 'EventNotFound' } | { kind: 'Closed' } | { kind: 'TooManyGuests'; max: number };

export function decideRsvp(event: EventCapacity, guests: number, now: Date): Result<RsvpOutcome, RsvpError> {
  if (event.rsvpClosesAt < now) return Result.fail({ kind: 'Closed' });
  if (guests > event.maxGuestsPerRsvp) return Result.fail({ kind: 'TooManyGuests', max: event.maxGuestsPerRsvp });
  const seats = 1 + guests;
  if (event.attending + seats > event.capacity) return Result.ok({ kind: 'Waitlisted' });
  return Result.ok({ kind: 'Confirmed', seats });
}
```

#### 2. Application Layer (`src/application/Rsvp.ts`)
```typescript
import { Result } from '../shared/Result';
import { EventCapacity, RsvpError, RsvpOutcome, decideRsvp } from '../domain/rsvp';

export interface RsvpWrites {
  confirm(userId: string, guests: number, seats: number): void;
  waitlist(userId: string, guests: number): void;
}

export interface EventStore {
  /** Runs `work` atomically with the current event state (null if the event does not exist). */
  transact<T>(eventId: string, work: (event: EventCapacity | null, writes: RsvpWrites) => T): Promise<T>;
}

export class Rsvp {
  constructor(private readonly events: EventStore, private readonly now: () => Date) {}

  execute(eventId: string, userId: string, guests: number): Promise<Result<RsvpOutcome, RsvpError>> {
    return this.events.transact(eventId, (event, writes) => {
      if (!event) return Result.fail({ kind: 'EventNotFound' });
      const outcome = decideRsvp(event, guests, this.now());
      if (!outcome.success) return outcome;
      if (outcome.data.kind === 'Confirmed') writes.confirm(userId, guests, outcome.data.seats);
      else writes.waitlist(userId, guests);
      return outcome;
    });
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/FirestoreEventStore.ts`)
Firestore's `runTransaction`, `doc`, `serverTimestamp` and the `Timestamp.toDate()` conversion live only here: `transact` reads the event, builds a `RsvpWrites` that calls `tx.update(attending + seats)` and `tx.set` on the `rsvps` or `waitlist` sub-collection, then invokes `work`.

#### 4. Presentation Layer (`src/composables/useRsvp.ts`)
```typescript
function describe(error: RsvpError): string {
  switch (error.kind) {
    case 'EventNotFound': return 'Event not found';
    case 'Closed': return 'RSVP closed';
    case 'TooManyGuests': return `Max ${error.max} guests`;
  }
}

export function useRsvp(eventId: string, rsvpUseCase: Rsvp) {
  const error = ref<string | null>(null);
  const waitlisted = ref(false);

  async function rsvp(userId: string, guests: number) {
    error.value = null;
    const result = await rsvpUseCase.execute(eventId, userId, guests);
    if (!result.success) {
      error.value = describe(result.error);
      return;
    }
    waitlisted.value = result.data.kind === 'Waitlisted';
  }

  return { rsvp, error, waitlisted };
}
```
The view can now show the waitlist state on its own instead of reading it from an error message.

```typescript
// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be a positive number");
  }
}

export class InvalidCurrencyError extends MoneyError {
  constructor() {
    super("Currency must be a non-empty string");
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Cannot add money with different currencies");
  }
}

export class MoneyValueObject {
  private constructor(private readonly value: Money) {
    // Private constructor to enforce creation through factory methods
  }

  public static create(amount: number, currency: string): Money {
    if (amount < 0 || !Number.isFinite(amount)) {
      throw new InvalidAmountError();
    }

    if (!currency || typeof currency !== 'string') {
      throw new InvalidCurrencyError();
    }

    return {
      amount,
      currency
    };
  }

  public static createFromMoney(money: Money): Money {
    return this.create(money.amount, money.currency);
  }

  public add(other: Money): Money {
    if (this.value.currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    const newAmount = this.value.amount + other.amount;

    return {
      amount: newAmount,
      currency: this.value.currency
    };
  }

  public get amount(): number {
    return this.value.amount;
  }

  public get currency(): string {
    return this.value.currency;
  }

  public equals(other: Money): boolean {
    return this.value.amount === other.amount && 
           this.value.currency === other.currency;
  }
}
```

This implementation follows Clean Architecture principles by:

1. **Separating concerns**: The `Money` interface defines the structure, while `MoneyValueObject` provides the behavior
2. **Enforcing immutability**: The `Money` interface is readonly, and the value object is immutable
3. **Proper error handling**: Custom domain-specific errors that extend a base `MoneyError`
4. **Dependency Rule compliance**: No external dependencies in the domain layer
5. **Type safety**: Strict typing with no `any` types
6. **Value object semantics**: Equality based on value, not identity
7. **Validation**: Ensures positive amounts and valid currency strings
8. **Currency consistency**: Prevents addition of different currencies

The implementation provides:
- A factory method for creating valid `Money` instances
- An `add` method that validates currency consistency
- Immutable value objects
- Proper error handling with typed domain errors
- Strict typing throughout
- No dependencies on external libraries or frameworks

