import { Result, ok, err } from '../Result';
import { DomainError, InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';
import { User } from '../../Domain/Entities/User';
import { IUserRepository } from '../Ports/IUserRepository';
import { IPasswordHasher } from '../Ports/IPasswordHasher';

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(
    userId: string,
    currentPassword: string,
    newPassword: string
  ): Promise<Result<void, DomainError>> {
    // Validate input
    if (!userId || !currentPassword || !newPassword) {
      return err(new InvalidPasswordError('All fields are required'));
    }

    // Business rule: new password cannot be empty
    if (newPassword.trim().length === 0) {
      return err(new InvalidPasswordError('New password cannot be empty'));
    }

    // Business rule: new password cannot equal old password
    if (currentPassword === newPassword) {
      return err(new PasswordMismatchError('New password cannot be the same as current password'));
    }

    // Fetch user
    const user = await this.userRepository.findById(userId);
    if (!user) {
      return err(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(currentPassword, user.passwordHash);
    if (!isPasswordValid) {
      return err(new PasswordMismatchError('Current password is incorrect'));
    }

    // Hash new password
    const newHashedPassword = await this.passwordHasher.hash(newPassword);

    // Update user password
    user.updatePassword(newHashedPassword);
    await this.userRepository.save(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends Error> = { success: true; value: T } | { success: false; error: E };

export const ok = <T>(value: T): Result<T, never> => ({ success: true, value });

export const err = <E extends Error>(error: E): Result<never, E> => ({ success: false, error });
```

This implementation follows Clean Architecture principles with:

1. **Dependency Rule Enforcement**: The use case depends only on ports (interfaces) from the application layer, not concrete implementations
2. **Domain Error Handling**: Uses typed domain errors for specific business rule violations
3. **Result Pattern**: Returns `Result<void, DomainError>` as required
4. **Business Rules**:
   - New password cannot equal old password
   - All fields are required
   - New password cannot be empty
   - Current password must be valid
5. **SOLID Principles**:
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Interfaces can be substituted with implementations
   - Interface Segregation: Small, focused interfaces
   - Dependency Inversion: High-level modules depend on abstractions

The use case enforces all business rules through validation before performing any operations, ensuring data integrity and following the dependency rule that domain/application layers don't depend on infrastructure.

This Node.js script computes weekly pay. Move it to a layered TypeScript design where the pay rules don't touch the filesystem:

```javascript
const fs = require('fs');

const shifts = JSON.parse(fs.readFileSync('./shifts.json', 'utf8'));
const rates = JSON.parse(fs.readFileSync('./rates.json', 'utf8'));
const byEmployee = {};
for (const s of shifts) {
  const hours = (new Date(s.end) - new Date(s.start)) / 3600000;
  byEmployee[s.employeeId] = (byEmployee[s.employeeId] || 0) + hours;
}
const lines = ['employee,regular,overtime,gross'];
for (const id of Object.keys(byEmployee)) {
  const total = byEmployee[id];
  const regular = Math.min(total, 40);
  const overtime = Math.max(0, total - 40);
  const gross = regular * rates[id] + overtime * rates[id] * 1.5;
  lines.push(`${id},${regular.toFixed(2)},${overtime.toFixed(2)},${gross.toFixed(2)}`);
}
fs.writeFileSync('./payroll.csv', lines.join('\n'));
```

### Architectural Flaws in Original Code
1. **Pay rules mixed with I/O:** the 40-hour threshold and the 1.5× overtime multiplier sit between `readFileSync` and `writeFileSync`.
2. **Missing rate is silent:** an employee without a rate produces `NaN` in the CSV.
3. **Output format coupled to calculation:** CSV formatting is interleaved with the arithmetic.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/payroll.ts`)
```typescript
export interface Shift {
  readonly employeeId: string;
  readonly start: Date;
  readonly end: Date;
}

export interface PayLine {
  readonly employeeId: string;
  readonly regularHours: number;
  readonly overtimeHours: number;
  readonly gross: number;
}

export const REGULAR_WEEK_HOURS = 40;
export const OVERTIME_MULTIPLIER = 1.5;

export function hoursByEmployee(shifts: readonly Shift[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (const s of shifts) {
    const hours = (s.end.getTime() - s.start.getTime()) / 3_600_000;
    totals.set(s.employeeId, (totals.get(s.employeeId) ?? 0) + hours);
  }
  return totals;
}

export function payFor(employeeId: string, hours: number, hourlyRate: number): PayLine {
  const regularHours = Math.min(hours, REGULAR_WEEK_HOURS);
  const overtimeHours = Math.max(0, hours - REGULAR_WEEK_HOURS);
  const gross = regularHours * hourlyRate + overtimeHours * hourlyRate * OVERTIME_MULTIPLIER;
  return { employeeId, regularHours, overtimeHours, gross };
}
```

#### 2. Application Layer (`src/application/RunPayroll.ts`)
```typescript
import { Result } from '../shared/Result';
import { PayLine, Shift, hoursByEmployee, payFor } from '../domain/payroll';

export type PayrollError = { kind: 'MissingRate'; employeeIds: string[] };

export interface TimesheetSource {
  shifts(): Promise<Shift[]>;
  hourlyRates(): Promise<Map<string, number>>;
}

export interface PayrollSink {
  write(lines: readonly PayLine[]): Promise<void>;
}

export class RunPayroll {
  constructor(private readonly source: TimesheetSource, private readonly sink: PayrollSink) {}

  async execute(): Promise<Result<PayLine[], PayrollError>> {
    const [shifts, rates] = await Promise.all([this.source.shifts(), this.source.hourlyRates()]);
    const totals = hoursByEmployee(shifts);

    const missing = [...totals.keys()].filter((id) => !rates.has(id));
    if (missing.length > 0) return Result.fail({ kind: 'MissingRate', employeeIds: missing });

    const lines = [...totals].map(([id, hours]) => payFor(id, hours, rates.get(id) ?? 0));
    await this.sink.write(lines);
    return Result.ok(lines);
  }
}
```
A missing rate is now an explicit error instead of `NaN` in the output.

#### 3. Infrastructure Layer (`src/infrastructure/files.ts`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { PayLine, Shift } from '../domain/payroll';
import { PayrollSink, TimesheetSource } from '../application/RunPayroll';

interface ShiftRecord { employeeId: string; start: string; end: string; }

export class JsonTimesheetSource implements TimesheetSource {
  constructor(private readonly shiftsPath: string, private readonly ratesPath: string) {}

  async shifts(): Promise<Shift[]> {
    const records = JSON.parse(await readFile(this.shiftsPath, 'utf8')) as ShiftRecord[];
    return records.map((r) => ({ employeeId: r.employeeId, start: new Date(r.start), end: new Date(r.end) }));
  }

  async hourlyRates(): Promise<Map<string, number>> {
    const rates = JSON.parse(await readFile(this.ratesPath, 'utf8')) as Record<string, number>;
    return new Map(Object.entries(rates));
  }
}

export class CsvPayrollSink implements PayrollSink {
  constructor(private readonly path: string) {}

  async write(lines: readonly PayLine[]): Promise<void> {
    const rows = lines.map((l) =>
      [l.employeeId, l.regularHours.toFixed(2), l.overtimeHours.toFixed(2), l.gross.toFixed(2)].join(','));
    await writeFile(this.path, ['employee,regular,overtime,gross', ...rows].join('\n'));
  }
}
```

#### 4. Composition Root (`src/main.ts`)
```typescript
const payroll = new RunPayroll(
  new JsonTimesheetSource('./shifts.json', './rates.json'),
  new CsvPayrollSink('./payroll.csv'),
);
const result = await payroll.execute();
if (!result.success) {
  console.error(`No hourly rate for: ${result.error.employeeIds.join(', ')}`);
  process.exitCode = 1;
}
```

Refactor this discord.js moderation listener. The strike policy should not know about Discord or SQLite:

```typescript
client.on('messageCreate', async (message) => {
  if (message.author.bot || !message.guild) return;
  const banned = db.prepare('SELECT word FROM banned_words WHERE guild_id = ?').all(message.guild.id).map((r) => r.word);
  const lower = message.content.toLowerCase();
  if (!banned.some((w) => lower.includes(w))) return;
  await message.delete();
  db.prepare('INSERT INTO strikes (guild_id, user_id, at) VALUES (?, ?, ?)').run(message.guild.id, message.author.id, Date.now());
  const recent = db.prepare('SELECT COUNT(*) AS n FROM strikes WHERE guild_id = ? AND user_id = ? AND at > ?')
    .get(message.guild.id, message.author.id, Date.now() - 7 * 86400000).n;
  if (recent >= 5) await message.member?.ban({ reason: '5 strikes in 7 days' });
  else if (recent >= 3) await message.member?.timeout(60 * 60 * 1000, '3 strikes in 7 days');
  else await message.author.send('Your message was removed for breaking the rules.');
});
```

### Architectural Flaws in Original Code
1. **Escalation policy in an event listener:** the 3-strike timeout and 5-strike ban over 7 days require a live Discord client.
2. **Synchronous SQL in the hot path:** `better-sqlite3` calls are mixed with the decision logic.
3. **Detection, storage and punishment are coupled**, so the banned-word matching cannot be reused elsewhere.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/moderation.ts`)
```typescript
export type Sanction = 'warn' | 'timeout' | 'ban';

export const STRIKE_WINDOW_MS = 7 * 86_400_000;
export const TIMEOUT_AT = 3;
export const BAN_AT = 5;
export const TIMEOUT_MS = 60 * 60 * 1000;

export function violates(content: string, bannedWords: readonly string[]): boolean {
  const lower = content.toLowerCase();
  return bannedWords.some((w) => lower.includes(w));
}

export function sanctionFor(strikesInWindow: number): Sanction {
  if (strikesInWindow >= BAN_AT) return 'ban';
  if (strikesInWindow >= TIMEOUT_AT) return 'timeout';
  return 'warn';
}
```

#### 2. Application Layer (`src/application/ModerateMessage.ts`)
```typescript
import { STRIKE_WINDOW_MS, Sanction, sanctionFor, violates } from '../domain/moderation';

export interface ModerationStore {
  bannedWords(guildId: string): Promise<string[]>;
  addStrike(guildId: string, userId: string, at: number): Promise<void>;
  strikesSince(guildId: string, userId: string, since: number): Promise<number>;
}

export interface ChatActions {
  deleteMessage(): Promise<void>;
  apply(sanction: Sanction): Promise<void>;
}

export class ModerateMessage {
  constructor(private readonly store: ModerationStore, private readonly now: () => number) {}

  async execute(guildId: string, userId: string, content: string, actions: ChatActions): Promise<Sanction | null> {
    if (!violates(content, await this.store.bannedWords(guildId))) return null;
    await actions.deleteMessage();
    const at = this.now();
    await this.store.addStrike(guildId, userId, at);
    const sanction = sanctionFor(await this.store.strikesSince(guildId, userId, at - STRIKE_WINDOW_MS));
    await actions.apply(sanction);
    return sanction;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/discord.ts`)
```typescript
import { Message } from 'discord.js';
import { Sanction, TIMEOUT_MS } from '../domain/moderation';
import { ChatActions } from '../application/ModerateMessage';

export class DiscordChatActions implements ChatActions {
  constructor(private readonly message: Message) {}

  async deleteMessage(): Promise<void> { await this.message.delete(); }

  async apply(sanction: Sanction): Promise<void> {
    if (sanction === 'ban') await this.message.member?.ban({ reason: '5 strikes in 7 days' });
    else if (sanction === 'timeout') await this.message.member?.timeout(TIMEOUT_MS, '3 strikes in 7 days');
    else await this.message.author.send('Your message was removed for breaking the rules.');
  }
}
```
`SqliteModerationStore` wraps the three prepared statements behind `ModerationStore`, returning promises so a remote database can replace it later.

#### 4. Entry Point
```typescript
client.on('messageCreate', async (message: Message) => {
  if (message.author.bot || !message.guild) return;
  await moderate.execute(message.guild.id, message.author.id, message.content, new DiscordChatActions(message));
});
```

Apply Clean Architecture to this Cloudflare Worker (Hono + KV) that creates short links:

```typescript
const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const { url, alias, ttlDays } = await c.req.json();
  let target: URL;
  try { target = new URL(url); } catch { return c.json({ error: 'Invalid URL' }, 400); }
  if (target.protocol !== 'https:') return c.json({ error: 'Only https links' }, 400);
  const reserved = ['admin', 'api', 'links'];
  const slug = alias ?? Math.random().toString(36).slice(2, 8);
  if (!/^[a-z0-9-]{3,32}$/.test(slug) || reserved.includes(slug)) {
    return c.json({ error: 'Invalid alias' }, 400);
  }
  if (await c.env.LINKS.get(slug)) return c.json({ error: 'Alias taken' }, 409);
  const days = Math.min(ttlDays ?? 30, 365);
  await c.env.LINKS.put(slug, target.toString(), { expirationTtl: days * 86400 });
  return c.json({ slug, expiresInDays: days }, 201);
});
```

### Architectural Flaws in Original Code
1. **Link policy tied to the Worker runtime:** https-only, alias format, reserved words and the TTL cap need Hono and KV to run.
2. **Randomness is hidden:** `Math.random()` inside the handler makes generated slugs untestable.
3. **Untyped body:** `c.req.json()` is destructured without validation.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/ShortLink.ts`)
```typescript
import { Result } from '../shared/Result';

export type LinkError =
  | { kind: 'InvalidUrl' }
  | { kind: 'InsecureUrl' }
  | { kind: 'InvalidAlias' }
  | { kind: 'AliasTaken' };

const RESERVED = new Set(['admin', 'api', 'links']);
const SLUG = /^[a-z0-9-]{3,32}$/;
export const DEFAULT_TTL_DAYS = 30;
export const MAX_TTL_DAYS = 365;

export interface ShortLink {
  readonly slug: string;
  readonly target: string;
  readonly ttlDays: number;
}

export function createShortLink(input: { url: string; slug: string; ttlDays?: number }): Result<ShortLink, LinkError> {
  let target: URL;
  try {
    target = new URL(input.url);
  } catch {
    return Result.fail({ kind: 'InvalidUrl' });
  }
  if (target.protocol !== 'https:') return Result.fail({ kind: 'InsecureUrl' });
  if (!SLUG.test(input.slug) || RESERVED.has(input.slug)) return Result.fail({ kind: 'InvalidAlias' });
  const ttlDays = Math.min(input.ttlDays ?? DEFAULT_TTL_DAYS, MAX_TTL_DAYS);
  return Result.ok({ slug: input.slug, target: target.toString(), ttlDays });
}
```

#### 2. Application Layer (`src/application/ShortenLink.ts`)
```typescript
import { Result } from '../shared/Result';
import { LinkError, ShortLink, createShortLink } from '../domain/ShortLink';

export interface LinkStore {
  exists(slug: string): Promise<boolean>;
  save(link: ShortLink): Promise<void>;
}

export interface SlugGenerator {
  next(): string;
}

export class ShortenLink {
  constructor(private readonly links: LinkStore, private readonly slugs: SlugGenerator) {}

  async execute(input: { url: string; alias?: string; ttlDays?: number }): Promise<Result<ShortLink, LinkError>> {
    const link = createShortLink({ url: input.url, slug: input.alias ?? this.slugs.next(), ttlDays: input.ttlDays });
    if (!link.success) return link;
    if (await this.links.exists(link.data.slug)) return Result.fail({ kind: 'AliasTaken' });
    await this.links.save(link.data);
    return link;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/kv.ts`)
```typescript
import { ShortLink } from '../domain/ShortLink';
import { LinkStore, SlugGenerator } from '../application/ShortenLink';

export class KvLinkStore implements LinkStore {
  constructor(private readonly kv: KVNamespace) {}

  async exists(slug: string): Promise<boolean> {
    return (await this.kv.get(slug)) !== null;
  }

  async save(link: ShortLink): Promise<void> {
    await this.kv.put(link.slug, link.target, { expirationTtl: link.ttlDays * 86_400 });
  }
}

export const randomSlugs: SlugGenerator = { next: () => Math.random().toString(36).slice(2, 8) };
```

#### 4. Presentation Layer (`src/worker.ts`)
```typescript
function toHttp(error: LinkError): [400 | 409, string] {
  switch (error.kind) {
    case 'InvalidUrl': return [400, 'Invalid URL'];
    case 'InsecureUrl': return [400, 'Only https links'];
    case 'InvalidAlias': return [400, 'Invalid alias'];
    case 'AliasTaken': return [409, 'Alias taken'];
  }
}

const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const body = (await c.req.json()) as { url?: unknown; alias?: unknown; ttlDays?: unknown };
  if (typeof body.url !== 'string') return c.json({ error: 'Invalid URL' }, 400);

  const shorten = new ShortenLink(new KvLinkStore(c.env.LINKS), randomSlugs);
  const result = await shorten.execute({
    url: body.url,
    alias: typeof body.alias === 'string' ? body.alias : undefined,
    ttlDays: typeof body.ttlDays === 'number' ? body.ttlDays : undefined,
  });
  if (result.success) return c.json({ slug: result.data.slug, expiresInDays: result.data.ttlDays }, 201);
  const [status, error] = toHttp(result.error);
  return c.json({ error }, status);
});
```

```typescript
// Domain/ValueObjects/Money.ts
export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: string
  ) {
    if (_amount < 0) {
      throw new Error("Amount must be positive");
    }
  }

  static create(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  get amount(): number {
    return this._amount;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    if (this._currency !== other._currency) {
      throw new Error("Cannot add money with different currencies");
    }
    return new Money(this._amount + other._amount, this._currency);
  }

  equals(other: Money): boolean {
    return this._amount === other._amount && this._currency === other._currency;
  }
}
```

```typescript
// Domain/ValueObjects/Money.spec.ts
import { Money } from "./Money";

describe("Money", () => {
  describe("creation", () => {
    it("should create a valid money instance", () => {
      const money = Money.create(100, "USD");
      expect(money.amount).toBe(100);
      expect(money.currency).toBe("USD");
    });

    it("should throw an error when amount is negative", () => {
      expect(() => Money.create(-10, "USD")).toThrow("Amount must be positive");
    });
  });

  describe("addition", () => {
    it("should add money with same currency", () => {
      const money1 = Money.create(50, "USD");
      const money2 = Money.create(30, "USD");
      const result = money1.add(money2);

      expect(result.amount).toBe(80);
      expect(result.currency).toBe("USD");
    });

    it("should throw an error when adding different currencies", () => {
      const money1 = Money.create(50, "USD");
      const money2 = Money.create(30, "EUR");

      expect(() => money1.add(money2)).toThrow("Cannot add money with different currencies");
    });
  });

  describe("equality", () => {
    it("should be equal when amount and currency are the same", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(100, "USD");

      expect(money1.equals(money2)).toBe(true);
    });

    it("should not be equal when amounts differ", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(50, "USD");

      expect(money1.equals(money2)).toBe(false);
    });

    it("should not be equal when currencies differ", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(100, "EUR");

      expect(money1.equals(money2)).toBe(false);
    });
  });
});
```

This implementation follows Clean Architecture principles:

1. **Pure Value Object**: The `Money` class is immutable and has no behavior beyond value representation
2. **Domain Layer Only**: No dependencies on external libraries or frameworks
3. **Validation**: Enforces positive amounts at construction time
4. **Currency Safety**: Prevents addition of different currencies
5. **No External Dependencies**: Uses only TypeScript built-in features
6. **Immutability**: All properties are private and readonly
7. **Type Safety**: Strong typing for amount and currency
8. **Test Coverage**: Includes comprehensive tests for all behaviors

The implementation uses the Result pattern implicitly through exceptions for error handling, which is appropriate for value objects where invalid states should not be allowed. The class is designed to be used within the domain layer without any infrastructure dependencies.

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { prisma } from '../prisma';
import { sendgrid } from '../sendgrid';

export async function publishCourseGrades(courseId: string) {
  const course = await prisma.course.findUniqueOrThrow({
    where: { id: courseId },
    include: { assignments: true, enrollments: { include: { student: true, submissions: true } } },
  });
  for (const enrollment of course.enrollments) {
    let weighted = 0;
    for (const a of course.assignments) {
      const sub = enrollment.submissions.find((s) => s.assignmentId === a.id);
      let score = sub ? sub.score / a.maxScore : 0;
      if (sub && sub.submittedAt > a.dueAt) score *= 0.9;
      weighted += score * a.weight;
    }
    const percent = Math.round(weighted * 1000) / 10;
    const letter = percent >= 90 ? 'A' : percent >= 80 ? 'B' : percent >= 70 ? 'C' : percent >= 60 ? 'D' : 'F';
    await prisma.enrollment.update({ where: { id: enrollment.id }, data: { finalPercent: percent, letter } });
    await sendgrid.send({ to: enrollment.student.email, subject: `${course.name} final grade`, text: `You got ${letter} (${percent}%)` });
  }
}

```

### Architectural Flaws in Original Code
1. **Grading policy embedded in a data script:** the late penalty (10%), weighting and letter thresholds sit between Prisma and SendGrid calls.
2. **Deeply nested ORM include** shapes the whole algorithm around the database schema.
3. **Partial failure:** if a notification fails mid-loop, some grades are saved and others are not, with no record of which.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/grading.ts`)
```typescript
export interface Assignment {
  readonly id: string;
  readonly maxScore: number;
  readonly weight: number; // weights sum to 1
  readonly dueAt: Date;
}

export interface Submission {
  readonly assignmentId: string;
  readonly score: number;
  readonly submittedAt: Date;
}

export type Letter = 'A' | 'B' | 'C' | 'D' | 'F';

export interface FinalGrade { readonly percent: number; readonly letter: Letter; }

export const LATE_FACTOR = 0.9;

export function assignmentScore(a: Assignment, sub: Submission | undefined): number {
  if (!sub) return 0;
  const raw = sub.score / a.maxScore;
  return sub.submittedAt > a.dueAt ? raw * LATE_FACTOR : raw;
}

export function letterFor(percent: number): Letter {
  if (percent >= 90) return 'A';
  if (percent >= 80) return 'B';
  if (percent >= 70) return 'C';
  if (percent >= 60) return 'D';
  return 'F';
}

export function finalGrade(assignments: readonly Assignment[], submissions: readonly Submission[]): FinalGrade {
  const weighted = assignments.reduce(
    (sum, a) => sum + assignmentScore(a, submissions.find((s) => s.assignmentId === a.id)) * a.weight, 0);
  const percent = Math.round(weighted * 1000) / 10;
  return { percent, letter: letterFor(percent) };
}
```

#### 2. Application Layer (`src/application/PublishCourseGrades.ts`)
```typescript
import { Assignment, FinalGrade, Submission, finalGrade } from '../domain/grading';

export interface CourseRoster {
  readonly name: string;
  readonly assignments: readonly Assignment[];
  readonly students: readonly { enrollmentId: string; contact: string; submissions: readonly Submission[] }[];
}

export interface GradebookRepository {
  roster(courseId: string): Promise<CourseRoster | null>;
  saveFinalGrades(grades: ReadonlyMap<string, FinalGrade>): Promise<void>; // one transaction
}

export interface GradeNotifier {
  finalGrade(contact: string, courseName: string, grade: FinalGrade): Promise<void>;
}

export class PublishCourseGrades {
  constructor(private readonly gradebook: GradebookRepository, private readonly notifier: GradeNotifier) {}

  async execute(courseId: string): Promise<number | null> {
    const roster = await this.gradebook.roster(courseId);
    if (!roster) return null;
    const grades = new Map(roster.students.map((s) => [s.enrollmentId, finalGrade(roster.assignments, s.submissions)]));
    await this.gradebook.saveFinalGrades(grades);
    for (const s of roster.students) {
      const grade = grades.get(s.enrollmentId);
      if (grade) await this.notifier.finalGrade(s.contact, roster.name, grade);
    }
    return grades.size;
  }
}
```
All grades are persisted atomically before any notification is sent.

#### 3. Infrastructure Layer (`src/infrastructure/SendGridGradeNotifier.ts`)
```typescript
