```typescript
import { useState } from 'react';
import { supabase } from '../lib/supabase';

type Task = { id: string; title: string; status: 'todo' | 'doing' | 'done'; assignee: string | null };

export function TaskCard({ task, currentUser }: { task: Task; currentUser: string }) {
  const [error, setError] = useState('');

  async function advance() {
    const next = task.status === 'todo' ? 'doing' : task.status === 'doing' ? 'done' : null;
    if (!next) return setError('Task already done');
    if (next === 'doing' && task.assignee && task.assignee !== currentUser) {
      return setError('Only the assignee can start this task');
    }
    const { count } = await supabase.from('tasks').select('*', { count: 'exact', head: true })
      .eq('assignee', currentUser).eq('status', 'doing');
    if (next === 'doing' && (count ?? 0) >= 3) return setError('Finish a task before starting another');
    await supabase.from('tasks').update({ status: next, assignee: task.assignee ?? currentUser }).eq('id', task.id);
  }

  return (
    <div>
      <h3>{task.title}</h3>
      <button onClick={advance}>Advance</button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}

```

### Architectural Flaws in Original Code
1. **Workflow rules in a click handler:** status order, assignee ownership and the work-in-progress limit of 3 live in a React component.
2. **Database client in the UI:** Supabase queries run directly from the view.
3. **Inconsistent check order:** the WIP query runs even when the task is moving to `done`.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/task.ts`)
```typescript
import { Result } from '../shared/Result';

export type TaskStatus = 'todo' | 'doing' | 'done';

export interface Task {
  readonly id: string;
  readonly title: string;
  readonly status: TaskStatus;
  readonly assignee: string | null;
}

export type AdvanceError =
  | { kind: 'AlreadyDone' }
  | { kind: 'NotAssignee' }
  | { kind: 'WipLimitReached'; limit: number };

export const WIP_LIMIT = 3;

export function advance(task: Task, user: string, userTasksInProgress: number): Result<Task, AdvanceError> {
  if (task.status === 'done') return Result.fail({ kind: 'AlreadyDone' });
  if (task.status === 'todo') {
    if (task.assignee && task.assignee !== user) return Result.fail({ kind: 'NotAssignee' });
    if (userTasksInProgress >= WIP_LIMIT) return Result.fail({ kind: 'WipLimitReached', limit: WIP_LIMIT });
    return Result.ok({ ...task, status: 'doing', assignee: task.assignee ?? user });
  }
  return Result.ok({ ...task, status: 'done', assignee: task.assignee ?? user });
}
```

#### 2. Application Layer (`src/application/AdvanceTask.ts`)
```typescript
import { Result } from '../shared/Result';
import { AdvanceError, Task, advance } from '../domain/task';

export interface TaskStore {
  countInProgress(user: string): Promise<number>;
  update(task: Task): Promise<void>;
}

export class AdvanceTask {
  constructor(private readonly tasks: TaskStore) {}

  async execute(task: Task, user: string): Promise<Result<Task, AdvanceError>> {
    const inProgress = task.status === 'todo' ? await this.tasks.countInProgress(user) : 0;
    const next = advance(task, user, inProgress);
    if (!next.success) return next;
    await this.tasks.update(next.data);
    return next;
  }
}
