  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    isError: false,
    value
  };
}

export function error<E extends Error>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    isError: true,
    error
  };
}
