export class CsvGradeSink implements IGradeSink {
  constructor(private readonly path: string) {}

  async write(results: Array<{ name: string; grade: Grade }>): Promise<void> {
    await fs.writeFile(this.path, results.map((r) => `${r.name},${r.grade}`).join('\n'));
  }
}
```

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../../Shared/Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    // Validate input
    if (!request.userId) {
      return error(new InvalidPasswordError('User ID is required'));
    }

    if (!request.currentPassword) {
      return error(new InvalidPasswordError('Current password is required'));
    }

    if (!request.newPassword) {
      return error(new InvalidPasswordError('New password is required'));
    }

    // Check if user exists
    const user = await this.userRepository.findById(request.userId);
    if (!user) {
      return error(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      request.currentPassword,
      user.passwordHash
    );

    if (!isPasswordValid) {
      return error(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      request.newPassword,
      user.passwordHash
    );

    if (isSamePassword) {
      return error(new InvalidPasswordError('New password cannot be the same as the current password'));
    }

    // Hash new password
    const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}
```

This implementation follows Clean Architecture principles with:

1. **Dependency Rule Enforcement**: The use case depends only on domain interfaces (`IUserRepository`, `IPasswordHasher`) and doesn't depend on any external libraries or infrastructure.

2. **Business Rules**: Implements the rule that new passwords cannot equal old passwords by comparing the new password with the existing hash.

3. **Result Pattern**: Returns `Result<void, DomainError>` as required, using the `ok` and `error` constructors.

4. **Typed Domain Errors**: Uses specific error types that extend `DomainError` for clear error handling.

5. **Strict Types**: No `any` types used; all interfaces and types are properly defined.

6. **SOLID Principles**: 
   - Single Responsibility: The use case handles only password changing logic
   - Dependency Inversion: Depends on abstractions, not concrete implementations
   - Open/Closed: Easy to extend with new validation rules

The use case handles all required validation scenarios including:
- Missing input parameters
- Non-existent users
- Incorrect current passwords
- Attempting to reuse the same password

Critique this service with the Dependency Inversion Principle and SOLID and refactor it:

```typescript
class OrderService {
  private db = new MySqlDatabase('prod-host', 3306);
  private mailer = new SmtpMailer('smtp.company.com');

  place(order: Order) {
    this.db.insert('orders', order);
    this.mailer.send(order.customerContact, 'Order placed');
  }
}
```

### SOLID Critique
- **DIP (violated):** the high-level `OrderService` instantiates low-level `MySqlDatabase` and `SmtpMailer`, so it depends on concrete details.
- **Testability:** tests would hit a production host and a real SMTP server.
- **OCP/SRP:** swapping the database or mail provider means editing the service, which should only hold ordering logic.

---

### Refactoring: depend on abstractions, inject them
```typescript
export interface OrderStore {
  save(order: Order): Promise<void>;
}

export interface Notifier {
  notify(contact: string, message: string): Promise<void>;
}

export class OrderService {
  constructor(
    private readonly store: OrderStore,
    private readonly notifier: Notifier,
  ) {}

  async place(order: Order): Promise<void> {
    await this.store.save(order);
    await this.notifier.notify(order.customerContact, 'Order placed');
  }
}
```

Concrete implementations (`MySqlOrderStore`, `SmtpNotifier`) live in the infrastructure layer and are wired in the composition root. Tests inject in-memory fakes, and changing providers no longer touches `OrderService`.

Refactor this Apollo GraphQL resolver for booking clinic appointments. Separate the scheduling rules from Knex and GraphQL:

```typescript
const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const start = new Date(args.startsAt);
      const end = new Date(start.getTime() + 30 * 60000);
      const hour = start.getUTCHours();
      if (hour < 8 || hour >= 17 || start.getUTCMinutes() % 30 !== 0) {
        throw new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
      }
      const clash = await knex('appointments')
        .where({ doctor_id: args.doctorId })
        .andWhere('starts_at', '<', end)
        .andWhere('ends_at', '>', start)
        .first();
      if (clash) throw new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
      const [row] = await knex('appointments')
        .insert({ doctor_id: args.doctorId, patient_id: args.patientId, starts_at: start, ends_at: end })
        .returning('*');
      return row;
    },
  },
};
```

### Architectural Flaws in Original Code
1. **Scheduling policy inside a resolver:** working hours, the 30-minute grid and slot length live next to `GraphQLError`.
2. **Query builder in the API layer:** the overlap rule is expressed only as SQL, so it cannot be tested in memory.
3. **Raw rows returned:** the GraphQL schema is coupled to database column names.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Slot.ts`)
```typescript
import { Result } from '../shared/Result';

export type BookingError = { kind: 'OutsideWorkingHours' } | { kind: 'SlotTaken' };

export class Slot {
  static readonly LENGTH_MINUTES = 30;
  static readonly OPENS_AT_HOUR = 8;
  static readonly CLOSES_AT_HOUR = 17;

  private constructor(readonly start: Date, readonly end: Date) {}

  static at(start: Date): Result<Slot, BookingError> {
    const hour = start.getUTCHours();
    const onGrid = start.getUTCMinutes() % Slot.LENGTH_MINUTES === 0;
    if (hour < Slot.OPENS_AT_HOUR || hour >= Slot.CLOSES_AT_HOUR || !onGrid) {
      return Result.fail({ kind: 'OutsideWorkingHours' });
    }
    return Result.ok(new Slot(start, new Date(start.getTime() + Slot.LENGTH_MINUTES * 60_000)));
  }

  overlaps(other: { start: Date; end: Date }): boolean {
    return other.start < this.end && other.end > this.start;
  }
}

export interface Appointment {
  readonly id?: string;
  readonly doctorId: string;
  readonly patientId: string;
  readonly start: Date;
  readonly end: Date;
}
```

#### 2. Application Layer (`src/application/BookAppointment.ts`)
```typescript
import { Result } from '../shared/Result';
import { Appointment, BookingError, Slot } from '../domain/Slot';

export interface AppointmentRepository {
  forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]>;
  add(appointment: Appointment): Promise<Appointment>;
}

export class BookAppointment {
  constructor(private readonly appointments: AppointmentRepository) {}

  async execute(input: { doctorId: string; patientId: string; startsAt: Date }): Promise<Result<Appointment, BookingError>> {
    const slot = Slot.at(input.startsAt);
    if (!slot.success) return slot;

    const existing = await this.appointments.forDoctorBetween(input.doctorId, slot.data.start, slot.data.end);
    if (existing.some((a) => slot.data.overlaps(a))) return Result.fail({ kind: 'SlotTaken' });

    const booked = await this.appointments.add({
      doctorId: input.doctorId, patientId: input.patientId, start: slot.data.start, end: slot.data.end,
    });
    return Result.ok(booked);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/KnexAppointmentRepository.ts`)
```typescript
import { Knex } from 'knex';
import { Appointment } from '../domain/Slot';
import { AppointmentRepository } from '../application/BookAppointment';

interface AppointmentRow { id: string; doctor_id: string; patient_id: string; starts_at: Date; ends_at: Date; }

const toAppointment = (r: AppointmentRow): Appointment =>
  ({ id: r.id, doctorId: r.doctor_id, patientId: r.patient_id, start: r.starts_at, end: r.ends_at });

export class KnexAppointmentRepository implements AppointmentRepository {
  constructor(private readonly knex: Knex) {}

  async forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]> {
    const rows = await this.knex<AppointmentRow>('appointments')
      .where({ doctor_id: doctorId }).andWhere('starts_at', '<', to).andWhere('ends_at', '>', from);
    return rows.map(toAppointment);
  }

  async add(a: Appointment): Promise<Appointment> {
    const [row] = await this.knex<AppointmentRow>('appointments')
      .insert({ doctor_id: a.doctorId, patient_id: a.patientId, starts_at: a.start, ends_at: a.end })
      .returning('*');
    return toAppointment(row);
  }
}
```

#### 4. Presentation Layer (resolver)
```typescript
function toGraphQLError(error: BookingError): GraphQLError {
  switch (error.kind) {
    case 'OutsideWorkingHours':
      return new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
    case 'SlotTaken':
      return new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
  }
}

export const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const result = await bookAppointment.execute({ ...args, startsAt: new Date(args.startsAt) });
      if (result.success) return result.data;
      throw toGraphQLError(result.error);
    },
  },
};
```

This release CLI decides the next version from git commits. Refactor it so the versioning rules are independent of git, yargs and the filesystem:

```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean' }).parseSync();
const git = simpleGit();
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const lastTag = (await git.tags()).latest ?? 'v0.0.0';
const log = await git.log({ from: lastTag, to: 'HEAD' });
let bump = 'none';
for (const c of log.all) {
  if (/BREAKING CHANGE/.test(c.body) || /^\w+(\(.+\))?!:/.test(c.message)) { bump = 'major'; break; }
  if (/^feat(\(.+\))?:/.test(c.message)) bump = 'minor';
  else if (/^fix(\(.+\))?:/.test(c.message) && bump === 'none') bump = 'patch';
}
if (bump === 'none') { console.log('Nothing to release'); process.exit(0); }
const [maj, min, pat] = pkg.version.split('.').map(Number);
const next = bump === 'major' ? `${maj + 1}.0.0` : bump === 'minor' ? `${maj}.${min + 1}.0` : `${maj}.${min}.${pat + 1}`;
if (!argv['dry-run']) {
  pkg.version = next;
  fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
  await git.addTag(`v${next}`);
}
console.log(`Next version: ${next}`);
```

### Architectural Flaws in Original Code
1. **Versioning policy in a script body:** the Conventional Commits rules cannot be tested without a git repository.
2. **Tooling everywhere:** `yargs`, `simple-git` and `fs` are used in the same flow that decides the bump.
3. **`process.exit` in the middle of logic** makes the flow impossible to reuse from another command.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/version.ts`)
```typescript
export type Bump = 'none' | 'patch' | 'minor' | 'major';

export interface Commit {
  readonly subject: string;
  readonly body: string;
}

const RANK: { readonly [B in Bump]: number } = { none: 0, patch: 1, minor: 2, major: 3 };

export function bumpFor(commit: Commit): Bump {
  if (/BREAKING CHANGE/.test(commit.body) || /^\w+(\(.+\))?!:/.test(commit.subject)) return 'major';
  if (/^feat(\(.+\))?:/.test(commit.subject)) return 'minor';
  if (/^fix(\(.+\))?:/.test(commit.subject)) return 'patch';
  return 'none';
}

export function releaseBump(commits: readonly Commit[]): Bump {
  return commits.map(bumpFor).reduce<Bump>((a, b) => (RANK[b] > RANK[a] ? b : a), 'none');
}

export function nextVersion(current: string, bump: Exclude<Bump, 'none'>): string {
  const [major, minor, patch] = current.split('.').map(Number);
  if (bump === 'major') return `${major + 1}.0.0`;
  if (bump === 'minor') return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}
```

#### 2. Application Layer (`src/application/PrepareRelease.ts`)
```typescript
import { Result } from '../shared/Result';
import { Commit, nextVersion, releaseBump } from '../domain/version';

export type ReleaseError = { kind: 'NothingToRelease' };

export interface Repository {
  latestTag(): Promise<string | null>;
  commitsSince(tag: string): Promise<Commit[]>;
  tag(name: string): Promise<void>;
}

export interface Manifest {
  currentVersion(): Promise<string>;
  setVersion(version: string): Promise<void>;
}

export class PrepareRelease {
  constructor(private readonly repo: Repository, private readonly manifest: Manifest) {}

  async execute(options: { dryRun: boolean }): Promise<Result<string, ReleaseError>> {
    const since = (await this.repo.latestTag()) ?? 'v0.0.0';
    const bump = releaseBump(await this.repo.commitsSince(since));
    if (bump === 'none') return Result.fail({ kind: 'NothingToRelease' });

    const next = nextVersion(await this.manifest.currentVersion(), bump);
    if (!options.dryRun) {
      await this.manifest.setVersion(next);
      await this.repo.tag(`v${next}`);
    }
    return Result.ok(next);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { SimpleGit } from 'simple-git';
import { Commit } from '../domain/version';
import { Manifest, Repository } from '../application/PrepareRelease';

export class SimpleGitRepository implements Repository {
  constructor(private readonly git: SimpleGit) {}
  async latestTag(): Promise<string | null> { return (await this.git.tags()).latest ?? null; }
  async commitsSince(tag: string): Promise<Commit[]> {
    const log = await this.git.log({ from: tag, to: 'HEAD' });
    return log.all.map((c) => ({ subject: c.message, body: c.body }));
  }
  async tag(name: string): Promise<void> { await this.git.addTag(name); }
}

export class PackageJsonManifest implements Manifest {
  constructor(private readonly path = 'package.json') {}
  async currentVersion(): Promise<string> {
    return (JSON.parse(await readFile(this.path, 'utf8')) as { version: string }).version;
  }
  async setVersion(version: string): Promise<void> {
    const pkg = JSON.parse(await readFile(this.path, 'utf8')) as Record<string, unknown>;
    await writeFile(this.path, JSON.stringify({ ...pkg, version }, null, 2) + '\n');
  }
}
```

#### 4. CLI Entry Point (`src/cli.ts`)
```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean', default: false }).parseSync();
const release = new PrepareRelease(new SimpleGitRepository(simpleGit()), new PackageJsonManifest());
const result = await release.execute({ dryRun: argv['dry-run'] });
console.log(result.success ? `Next version: ${result.data}` : 'Nothing to release');
```

Clean up this Fastify handler. Coupon rules, Redis keys and the HTTP reply are all in one place:

```typescript
fastify.post('/coupons/redeem', async (request, reply) => {
  const { code, customerId, orderTotal } = request.body as {
    code: string; customerId: string; orderTotal: number;
  };
  const raw = await redis.get(`coupon:${code.toUpperCase()}`);
  if (!raw) return reply.code(404).send({ error: 'Invalid coupon' });
  const coupon = JSON.parse(raw);
  if (new Date(coupon.expiresAt) < new Date()) return reply.code(410).send({ error: 'Coupon expired' });
  if (orderTotal < coupon.minOrder) return reply.code(422).send({ error: 'Order too small' });
  const used = await redis.sismember(`coupon:${code.toUpperCase()}:used`, customerId);
  if (used) return reply.code(409).send({ error: 'Already redeemed' });
  const discount = coupon.type === 'percent'
    ? Math.min(orderTotal * coupon.value / 100, coupon.maxDiscount ?? Infinity)
    : Math.min(coupon.value, orderTotal);
  await redis.sadd(`coupon:${code.toUpperCase()}:used`, customerId);
  return { discount: Math.round(discount * 100) / 100 };
});
```

### Architectural Flaws in Original Code
1. **Discount math in the transport layer:** percent caps and fixed-amount rules are buried in a Fastify callback.
2. **Storage format leaks:** Redis key naming and `JSON.parse` of an untyped blob live next to business decisions.
3. **Implicit time:** `new Date()` makes expiry impossible to test deterministically.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Coupon.ts`)
```typescript
import { Result } from '../shared/Result';

export type CouponError =
  | { kind: 'NotFound' }
  | { kind: 'Expired' }
  | { kind: 'BelowMinimum'; minOrder: number }
  | { kind: 'AlreadyRedeemed' };

export type DiscountRule =
  | { type: 'percent'; value: number; maxDiscount?: number }
  | { type: 'fixed'; value: number };

export class Coupon {
  constructor(
    readonly code: string,
    readonly rule: DiscountRule,
    readonly minOrder: number,
    readonly expiresAt: Date,
  ) {}

  static normalize(code: string): string { return code.toUpperCase(); }

  discountFor(orderTotal: number, now: Date): Result<number, CouponError> {
    if (this.expiresAt < now) return Result.fail({ kind: 'Expired' });
    if (orderTotal < this.minOrder) return Result.fail({ kind: 'BelowMinimum', minOrder: this.minOrder });
    const raw = this.rule.type === 'percent'
      ? Math.min((orderTotal * this.rule.value) / 100, this.rule.maxDiscount ?? Infinity)
      : Math.min(this.rule.value, orderTotal);
    return Result.ok(Math.round(raw * 100) / 100);
  }
}
```

#### 2. Application Layer (`src/application/RedeemCoupon.ts`)
```typescript
import { Result } from '../shared/Result';
import { Coupon, CouponError } from '../domain/Coupon';

export interface CouponRepository {
  find(code: string): Promise<Coupon | null>;
  hasRedeemed(code: string, customerId: string): Promise<boolean>;
  markRedeemed(code: string, customerId: string): Promise<void>;
}

export class RedeemCoupon {
  constructor(private readonly coupons: CouponRepository, private readonly now: () => Date) {}

  async execute(input: { code: string; customerId: string; orderTotal: number }): Promise<Result<number, CouponError>> {
    const code = Coupon.normalize(input.code);
    const coupon = await this.coupons.find(code);
    if (!coupon) return Result.fail({ kind: 'NotFound' });

    const discount = coupon.discountFor(input.orderTotal, this.now());
    if (!discount.success) return discount;

    if (await this.coupons.hasRedeemed(code, input.customerId)) {
      return Result.fail({ kind: 'AlreadyRedeemed' });
    }
    await this.coupons.markRedeemed(code, input.customerId);
    return discount;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/RedisCouponRepository.ts`)
```typescript
import type { Redis } from 'ioredis';
import { Coupon, DiscountRule } from '../domain/Coupon';
import { CouponRepository } from '../application/RedeemCoupon';

interface StoredCoupon {
  type: 'percent' | 'fixed';
  value: number;
  maxDiscount?: number;
  minOrder: number;
  expiresAt: string;
}

export class RedisCouponRepository implements CouponRepository {
  constructor(private readonly redis: Redis) {}

  async find(code: string): Promise<Coupon | null> {
    const raw = await this.redis.get(`coupon:${code}`);
    if (!raw) return null;
    const stored = JSON.parse(raw) as StoredCoupon;
    const rule: DiscountRule = stored.type === 'percent'
      ? { type: 'percent', value: stored.value, maxDiscount: stored.maxDiscount }
      : { type: 'fixed', value: stored.value };
    return new Coupon(code, rule, stored.minOrder, new Date(stored.expiresAt));
  }

  async hasRedeemed(code: string, customerId: string): Promise<boolean> {
    return (await this.redis.sismember(`coupon:${code}:used`, customerId)) === 1;
  }

  async markRedeemed(code: string, customerId: string): Promise<void> {
    await this.redis.sadd(`coupon:${code}:used`, customerId);
  }
}
```

#### 4. Presentation Layer (Fastify route)
```typescript
function toHttp(error: CouponError): [number, string] {
  switch (error.kind) {
    case 'NotFound': return [404, 'Invalid coupon'];
    case 'Expired': return [410, 'Coupon expired'];
    case 'BelowMinimum': return [422, 'Order too small'];
    case 'AlreadyRedeemed': return [409, 'Already redeemed'];
  }
}

fastify.post<{ Body: { code: string; customerId: string; orderTotal: number } }>(
  '/coupons/redeem',
  async (request, reply) => {
    const result = await redeemCoupon.execute(request.body);
    if (result.success) return { discount: result.data };
    const [status, error] = toHttp(result.error);
    return reply.code(status).send({ error });
  },
);
```

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionAlreadyExpiredError extends Error {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function success<T>(value: T): Success<T> {
  return { isSuccess: true, value };
}

export function failure<E>(error: E): Failure<E> {
  return { isSuccess: false, error };
}

// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, success, failure } from '../Domain/Result';
import { Subscription } from '../Domain/Entities/Subscription';
import { SubscriptionAlreadyExpiredError } from '../Domain/Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, CancelSubscriptionError>>;
}

export type CancelSubscriptionError = 
  | SubscriptionNotFoundError 
  | SubscriptionAlreadyExpiredError;

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, CancelSubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return failure(new SubscriptionNotFoundError());
      }

      const cancelledSubscription = subscription.cancel();

      await this.subscriptionRepository.save(cancelledSubscription);

      return success(cancelledSubscription);
    } catch (error) {
      if (error instanceof SubscriptionAlreadyExpiredError) {
        return failure(error);
      }
      throw error;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: The `Subscription` class contains only domain logic and has no dependencies on external frameworks or infrastructure
2. **Invariant Validation**: The `cancel()` method explicitly checks if the subscription is already expired and throws a typed error
3. **Result Pattern**: Uses a strict `Result<T, E>` type with `success()` and `failure()` factory functions
4. **Typed Errors**: Domain-specific error types that extend `Error` with descriptive names
5. **Dependency Rule Compliance**: The domain layer (Entities, Errors, Result) has no dependencies on external libraries or frameworks
6. **No `any` Type**: All types are explicitly defined with interfaces and types
7. **Type Safety**: Strict typing throughout with proper interfaces and type guards

The `CancelSubscriptionUseCase` validates that:
- The subscription exists
- The subscription is not already expired (invariant rule)
- Returns appropriate Result types with proper error handling

