// Domain/ValueObjects/Email.ts
import { Result, ok, err } from "../Result";
import { ValidationError } from "../Errors/ValidationError";

export class Email {
  private constructor(private readonly value: string) {
    // Private constructor to enforce creation through static factory method
  }

  // Factory method with validation
  static create(email: string): Result<Email, ValidationError> {
    // Check if email is empty or null
    if (!email || typeof email !== 'string') {
      return err(new ValidationError("Email cannot be empty or null"));
    }

    // Check if email is non-empty after trimming
    const trimmedEmail = email.trim();
    if (trimmedEmail.length === 0) {
      return err(new ValidationError("Email cannot be empty"));
    }

    // Normalize to lowercase
    const normalizedEmail = trimmedEmail.toLowerCase();

    // Validate email format using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(normalizedEmail)) {
      return err(new ValidationError("Email format is invalid"));
    }

    // Create and return the Email value object
    return ok(new Email(normalizedEmail));
  }

  // Getter for the email value
  getValue(): string {
    return this.value;
  }

  // Equality check
  equals(other: Email): boolean {
    return this.value === other.getValue();
  }

  // String representation
  toString(): string {
    return this.value;
  }
}

// Result type definition (if not already available)
export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export function ok<T, E>(value: T): Result<T, E> {
  return { ok: true, value };
}

export function err<T, E>(error: E): Result<T, E> {
  return { ok: false, error };
}
```

This implementation follows Clean Architecture principles:

1. **Pure Value Object**: The `Email` class is immutable and represents a value with no identity
2. **Invariant Validation**:
   - Ensures email is not empty or null
   - Validates email format using regex
   - Normalizes to lowercase
3. **Dependency Rule Compliance**: 
   - Domain layer (Email) doesn't depend on external libraries
   - Uses only native JavaScript/TypeScript features
4. **Result Pattern**: Returns `Result<Email, ValidationError>` for proper error handling
5. **SOLID Principles**:
   - Single Responsibility: Email class only handles email validation and representation
   - Open/Closed: Can be extended but not modified
   - Liskov Substitution: Email objects can be used wherever a string is expected (via getValue())
   - Interface Segregation: Minimal interface exposed
   - Dependency Inversion: Depends on abstractions (ValidationError, Result)

The factory method `create()` enforces all invariants and returns either a valid `Email` object or a `ValidationError` wrapped in a `Result` type.

This BullMQ worker computes reorder alerts for a store. Refactor it so the replenishment math is pure and the queue, Prisma and Slack are replaceable:

```typescript
new Worker('reorder-check', async (job) => {
  const since = new Date(Date.now() - 28 * 86400000);
  const products = await prisma.product.findMany({ where: { storeId: job.data.storeId, discontinued: false } });
  const alerts: string[] = [];
  for (const p of products) {
    const sold = await prisma.sale.aggregate({ _sum: { qty: true }, where: { productId: p.id, soldAt: { gte: since } } });
    const dailyDemand = (sold._sum.qty ?? 0) / 28;
    const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * 3);
    if (p.onHand <= reorderPoint) {
      const qty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * 14) - p.onHand);
      alerts.push(`${p.sku}: on hand ${p.onHand}, order ${qty}`);
    }
  }
  if (alerts.length) {
    await fetch(process.env.SLACK_WEBHOOK!, { method: 'POST', body: JSON.stringify({ text: alerts.join('\n') }) });
  }
}, { connection });
```

### Architectural Flaws in Original Code
1. **Replenishment formula hidden in a job:** the 28-day window, 3 days of safety stock and the 14-day order target can only be checked by running BullMQ.
2. **N+1 queries in the business loop:** sales are aggregated per product inside the decision logic.
3. **Notification format coupled to Slack:** alerts are built as Slack text strings.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/replenishment.ts`)
```typescript
export interface StockPosition {
  readonly sku: string;
  readonly onHand: number;
  readonly leadTimeDays: number;
  readonly minOrderQty: number;
  readonly unitsSold: number; // within the demand window
}

export interface ReorderSuggestion {
  readonly sku: string;
  readonly onHand: number;
  readonly orderQty: number;
}

export const DEMAND_WINDOW_DAYS = 28;
export const SAFETY_STOCK_DAYS = 3;
export const COVERAGE_DAYS = 14;

export function suggestReorder(p: StockPosition): ReorderSuggestion | null {
  const dailyDemand = p.unitsSold / DEMAND_WINDOW_DAYS;
  const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * SAFETY_STOCK_DAYS);
  if (p.onHand > reorderPoint) return null;
  const orderQty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * COVERAGE_DAYS) - p.onHand);
  return { sku: p.sku, onHand: p.onHand, orderQty };
}
```

#### 2. Application Layer (`src/application/CheckReorders.ts`)
```typescript
import { ReorderSuggestion, StockPosition, DEMAND_WINDOW_DAYS, suggestReorder } from '../domain/replenishment';

export interface StockReader {
  /** Active products of the store with units sold since `since`. */
  positions(storeId: string, since: Date): Promise<StockPosition[]>;
}

export interface ReorderNotifier {
  notify(storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void>;
}

export class CheckReorders {
  constructor(
    private readonly stock: StockReader,
    private readonly notifier: ReorderNotifier,
    private readonly now: () => Date,
  ) {}

  async execute(storeId: string): Promise<ReorderSuggestion[]> {
    const since = new Date(this.now().getTime() - DEMAND_WINDOW_DAYS * 86_400_000);
    const suggestions = (await this.stock.positions(storeId, since))
      .map(suggestReorder)
      .filter((s): s is ReorderSuggestion => s !== null);
    if (suggestions.length > 0) await this.notifier.notify(storeId, suggestions);
    return suggestions;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
One grouped query replaces the per-product aggregate.
```typescript
import { PrismaClient } from '@prisma/client';
import { ReorderSuggestion, StockPosition } from '../domain/replenishment';
import { ReorderNotifier, StockReader } from '../application/CheckReorders';

export class PrismaStockReader implements StockReader {
  constructor(private readonly prisma: PrismaClient) {}

  async positions(storeId: string, since: Date): Promise<StockPosition[]> {
    const products = await this.prisma.product.findMany({ where: { storeId, discontinued: false } });
    const sales = await this.prisma.sale.groupBy({
      by: ['productId'], _sum: { qty: true },
      where: { productId: { in: products.map((p) => p.id) }, soldAt: { gte: since } },
    });
    const sold = new Map(sales.map((s) => [s.productId, s._sum.qty ?? 0]));
    return products.map((p) => ({
      sku: p.sku, onHand: p.onHand, leadTimeDays: p.leadTimeDays,
      minOrderQty: p.minOrderQty, unitsSold: sold.get(p.id) ?? 0,
    }));
  }
}

export class SlackReorderNotifier implements ReorderNotifier {
  constructor(private readonly webhookUrl: string) {}

  async notify(_storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void> {
    const text = suggestions.map((s) => `${s.sku}: on hand ${s.onHand}, order ${s.orderQty}`).join('\n');
    await fetch(this.webhookUrl, { method: 'POST', body: JSON.stringify({ text }) });
  }
}
```

#### 4. Worker (`src/jobs/reorderWorker.ts`)
```typescript
import { Job, Worker } from 'bullmq';

const checkReorders = new CheckReorders(
  new PrismaStockReader(prisma),
  new SlackReorderNotifier(config.slackWebhookUrl),
  () => new Date(),
);

new Worker('reorder-check', async (job: Job<{ storeId: string }>) => {
  await checkReorders.execute(job.data.storeId);
}, { connection: config.redis });
```
The webhook URL is now read once into `config` at startup instead of with a non-null assertion inside the job.

