export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  static from(
    id: string,
    userId: string,
    status: 'active' | 'cancelled' | 'expired',
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      status,
      startDate,
      endDate,
      plan
    );
  }

  isExpired(): boolean {
    return new Date() > this.endDate;
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

