import { Result } from '../shared/Result';
import { Membership, MembershipError } from '../domain/Membership';

export interface MembershipRepository {
  findByUser(userId: string): Promise<Membership | null>;
  save(membership: Membership): Promise<void>;
}

export interface Clock {
  now(): Date;
}

export class PauseMembership {
  constructor(private readonly memberships: MembershipRepository, private readonly clock: Clock) {}

  async execute(userId: string, weeks: number): Promise<Result<Membership, MembershipError>> {
    const membership = await this.memberships.findByUser(userId);
    if (!membership) return Result.fail({ kind: 'NotFound' });
    const paused = membership.pause(weeks, this.clock.now());
    if (!paused.success) return paused;
    await this.memberships.save(membership);
    console.log(`Membership ${membership.id} paused for ${weeks} weeks`);
    return Result.ok(membership);
  }
}

