Refactor this transfer service toward Clean Architecture. Model failures as typed domain error classes, like our codebase does with a `DomainError` base class:

```typescript
export class TransferService {
  constructor(private readonly knex: Knex) {}

  async transfer(fromId: string, toId: string, amountCents: number, userId: string) {
    return this.knex.transaction(async (trx) => {
      const from = await trx('accounts').where({ id: fromId }).forUpdate().first();
      const to = await trx('accounts').where({ id: toId }).forUpdate().first();
      if (!from || !to) throw new Error('Account not found');
      if (from.owner_id !== userId) throw new Error('Forbidden');
      if (from.currency !== to.currency) throw new Error('Currency mismatch');
      const today = await trx('transfers').where({ from_id: fromId })
        .andWhere('created_at', '>=', trx.raw("date_trunc('day', now())")).sum('amount_cents as total').first();
      if (Number(today?.total ?? 0) + amountCents > 500000) throw new Error('Daily limit exceeded');
      if (from.balance_cents < amountCents) throw new Error('Insufficient funds');
      await trx('accounts').where({ id: fromId }).decrement('balance_cents', amountCents);
      await trx('accounts').where({ id: toId }).increment('balance_cents', amountCents);
      await trx('transfers').insert({ from_id: fromId, to_id: toId, amount_cents: amountCents });
    });
  }
}
```

### Architectural Flaws in Original Code
1. **Generic `Error` for every rule:** callers cannot distinguish a forbidden transfer from insufficient funds.
2. **Banking rules expressed as Knex calls:** ownership, currency, the daily limit and the balance check need a database to run.
3. **No positive-amount check:** a negative amount would move funds backwards.

---

### Clean Architecture Refactoring

#### 1. Domain Errors (`src/domain/errors.ts`)
```typescript
export abstract class DomainError extends Error {
  abstract readonly code: string;
}

export class AccountNotFoundError extends DomainError { readonly code = 'ACCOUNT_NOT_FOUND'; }
export class ForbiddenTransferError extends DomainError { readonly code = 'FORBIDDEN'; }
export class CurrencyMismatchError extends DomainError { readonly code = 'CURRENCY_MISMATCH'; }
export class InvalidAmountError extends DomainError { readonly code = 'INVALID_AMOUNT'; }
export class DailyLimitExceededError extends DomainError {
  readonly code = 'DAILY_LIMIT_EXCEEDED';
  constructor(readonly remainingCents: number) { super(`Daily limit exceeded, ${remainingCents} cents left`); }
}
export class InsufficientFundsError extends DomainError { readonly code = 'INSUFFICIENT_FUNDS'; }
```

#### 2. Domain Layer (`src/domain/Account.ts`)
```typescript
import { Result } from '../shared/Result';

export const DAILY_LIMIT_CENTS = 500_000;

export class Account {
  constructor(
    readonly id: string,
    readonly ownerId: string,
    readonly currency: string,
    private balance: number,
  ) {}

  get balanceCents(): number { return this.balance; }

  transferTo(target: Account, amountCents: number, requestedBy: string, sentToday: number): Result<void, DomainError> {
    if (!Number.isInteger(amountCents) || amountCents <= 0) return Result.fail(new InvalidAmountError('Amount must be positive'));
    if (this.ownerId !== requestedBy) return Result.fail(new ForbiddenTransferError('Forbidden'));
    if (this.currency !== target.currency) return Result.fail(new CurrencyMismatchError('Currency mismatch'));
    if (sentToday + amountCents > DAILY_LIMIT_CENTS) return Result.fail(new DailyLimitExceededError(DAILY_LIMIT_CENTS - sentToday));
    if (this.balance < amountCents) return Result.fail(new InsufficientFundsError('Insufficient funds'));
    this.balance -= amountCents;
    target.balance += amountCents;
    return Result.ok(undefined);
  }
}
```

#### 3. Application Layer (`src/application/TransferFunds.ts`)
```typescript
import { Result } from '../shared/Result';
import { Account } from '../domain/Account';
import { AccountNotFoundError, DomainError } from '../domain/errors';

export interface TransferUnit {
  lockAccounts(fromId: string, toId: string): Promise<[Account | null, Account | null]>;
  sentTodayCents(accountId: string): Promise<number>;
  record(from: Account, to: Account, amountCents: number): Promise<void>;
}

export interface Ledger {
  atomically<T>(work: (unit: TransferUnit) => Promise<T>): Promise<T>;
}

export class TransferFunds {
  constructor(private readonly ledger: Ledger) {}

  execute(input: { fromId: string; toId: string; amountCents: number; userId: string }): Promise<Result<void, DomainError>> {
    return this.ledger.atomically(async (unit) => {
      const [from, to] = await unit.lockAccounts(input.fromId, input.toId);
      if (!from || !to) return Result.fail(new AccountNotFoundError('Account not found'));
      const sentToday = await unit.sentTodayCents(from.id);
      const moved = from.transferTo(to, input.amountCents, input.userId, sentToday);
      if (!moved.success) return moved;
      await unit.record(from, to, input.amountCents);
      return Result.ok(undefined);
    });
  }
}
```

#### 4. Infrastructure Layer (`src/infrastructure/KnexLedger.ts`)
The Knex transaction, `forUpdate()` locks and the `date_trunc` query move unchanged into `KnexLedger.atomically`, which builds a `TransferUnit` over `trx`. A domain error returned inside it simply leaves the transaction without writes, so nothing needs to be thrown to roll back.

#### 5. Presentation Layer
```typescript
const STATUS: Record<string, number> = {
  ACCOUNT_NOT_FOUND: 404, FORBIDDEN: 403, CURRENCY_MISMATCH: 422,
  INVALID_AMOUNT: 422, DAILY_LIMIT_EXCEEDED: 429, INSUFFICIENT_FUNDS: 409,
};

export function httpStatusFor(error: DomainError): number {
  return STATUS[error.code] ?? 400;
}
```

Critique this class using SOLID and refactor it:

```typescript
class ShapeAreaService {
  area(shape: { kind: string; w?: number; h?: number; r?: number }): number {
    if (shape.kind === 'rect') return shape.w! * shape.h!;
    if (shape.kind === 'circle') return Math.PI * shape.r! ** 2;
    throw new Error('Unknown shape');
  }
}
```

### SOLID Critique
- **OCP (violated):** every new shape edits `area`.
- **Type safety:** optional fields plus non-null assertions (`!`) hide missing data until runtime.
- **SRP (borderline):** one class knows the geometry of every shape.

---

### Refactoring: polymorphism instead of a `kind` switch
```typescript
export interface Shape {
  area(): number;
}

export class Rectangle implements Shape {
  constructor(private readonly width: number, private readonly height: number) {}
  area(): number { return this.width * this.height; }
}

export class Circle implements Shape {
  constructor(private readonly radius: number) {}
  area(): number { return Math.PI * this.radius ** 2; }
}

export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + shape.area(), 0);
}
```

A triangle is now one new class. `totalArea` never changes (OCP), and each shape owns exactly the data it needs, so no optional fields or `!` are required.

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  canBeCancelled(): boolean {
    return this.isActive() && !this.isExpired();
  }

  cancel(): Subscription {
    if (!this.canBeCancelled()) {
      throw new SubscriptionCannotBeCancelledError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionCannotBeCancelledError extends Error {
  constructor() {
    super('Cannot cancel an expired subscription');
    this.name = 'SubscriptionCannotBeCancelledError';
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription } from '../Entities/Subscription';
import { SubscriptionCannotBeCancelledError } from '../Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError());
      }

      if (!subscription.canBeCancelled()) {
        return error(new SubscriptionCannotBeCancelledError());
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof SubscriptionCannotBeCancelledError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

// Result type implementation
export type Result<T, E extends Error> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    isError: false,
    value,
  };
}

export function error<E extends Error>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    isError: true,
    error,
  };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: `Subscription` is a simple entity with no dependencies on external frameworks or infrastructure
2. **Invariant Validation**: The `canBeCancelled()` method enforces that only active subscriptions can be cancelled
3. **Result Pattern**: Use cases return `Result<T, E>` with proper error types
4. **Typed Errors**: Specific domain errors are used instead of generic ones
5. **Dependency Rule**: Domain layer doesn't depend on any external libraries or frameworks
6. **No `any` Type**: All types are explicitly defined with interfaces and types
7. **SOLID Principles**: 
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Interface implementations work correctly
   - Interface Segregation: Clear separation of concerns
   - Dependency Inversion: Dependencies are injected through constructor

The `CancelSubscriptionUseCase` validates that:
- The subscription exists
- The subscription is not already expired
- The subscription is in an active state
- Returns appropriate errors when validation fails

Decouple the bidding rules in this Socket.IO handler from MongoDB and the socket layer:

```typescript
io.on('connection', (socket) => {
  socket.on('bid', async ({ auctionId, bidderId, amount }) => {
    const auction = await db.collection('auctions').findOne({ _id: new ObjectId(auctionId) });
    if (!auction) return socket.emit('bid:error', 'Auction not found');
    if (Date.now() > auction.endsAt.getTime()) return socket.emit('bid:error', 'Auction closed');
    if (auction.sellerId === bidderId) return socket.emit('bid:error', 'Sellers cannot bid');
    const current = auction.highestBid ?? auction.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    if (amount < current + step) return socket.emit('bid:error', `Minimum bid is ${current + step}`);
    let endsAt = auction.endsAt;
    if (auction.endsAt.getTime() - Date.now() < 120000) endsAt = new Date(Date.now() + 120000);
    await db.collection('auctions').updateOne({ _id: auction._id },
      { $set: { highestBid: amount, highestBidderId: bidderId, endsAt } });
    io.to(auctionId).emit('bid:accepted', { amount, bidderId, endsAt });
  });
});
```

### Architectural Flaws in Original Code
1. **Auction rules live in a socket listener:** bid increments, seller restrictions and the anti-sniping extension depend on Socket.IO.
2. **Persistence and broadcasting mixed with decisions:** MongoDB updates and room emits are interleaved with validation.
3. **Clock read four times:** `Date.now()` is called repeatedly, so a single bid can see different "now" values.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Auction.ts`)
```typescript
import { Result } from '../shared/Result';

export type BidError =
  | { kind: 'AuctionNotFound' }
  | { kind: 'AuctionClosed' }
  | { kind: 'SellerCannotBid' }
  | { kind: 'BidTooLow'; minimum: number };

export interface AcceptedBid { readonly amount: number; readonly bidderId: string; readonly endsAt: Date; }

export class Auction {
  static readonly EXTENSION_MS = 120_000;

  constructor(
    readonly id: string,
    readonly sellerId: string,
    readonly startingPrice: number,
    private endTime: Date,
    private highest: { amount: number; bidderId: string } | null,
  ) {}

  get endsAt(): Date { return this.endTime; }

  minimumNextBid(): number {
    const current = this.highest?.amount ?? this.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    return current + step;
  }

  placeBid(bidderId: string, amount: number, now: Date): Result<AcceptedBid, BidError> {
    if (now > this.endTime) return Result.fail({ kind: 'AuctionClosed' });
    if (bidderId === this.sellerId) return Result.fail({ kind: 'SellerCannotBid' });
    const minimum = this.minimumNextBid();
    if (amount < minimum) return Result.fail({ kind: 'BidTooLow', minimum });

    this.highest = { amount, bidderId };
    if (this.endTime.getTime() - now.getTime() < Auction.EXTENSION_MS) {
      this.endTime = new Date(now.getTime() + Auction.EXTENSION_MS); // anti-sniping
    }
    return Result.ok({ amount, bidderId, endsAt: this.endTime });
  }
}
```

#### 2. Application Layer (`src/application/PlaceBid.ts`)
```typescript
import { Result } from '../shared/Result';
import { AcceptedBid, Auction, BidError } from '../domain/Auction';

export interface AuctionRepository {
  findById(id: string): Promise<Auction | null>;
  saveBid(auction: Auction, bid: AcceptedBid): Promise<void>;
}

export interface BidBroadcaster {
  accepted(auctionId: string, bid: AcceptedBid): void;
}

export class PlaceBid {
  constructor(
    private readonly auctions: AuctionRepository,
    private readonly broadcaster: BidBroadcaster,
    private readonly clock: () => Date,
  ) {}

  async execute(auctionId: string, bidderId: string, amount: number): Promise<Result<AcceptedBid, BidError>> {
    const auction = await this.auctions.findById(auctionId);
    if (!auction) return Result.fail({ kind: 'AuctionNotFound' });

    const bid = auction.placeBid(bidderId, amount, this.clock());
    if (!bid.success) return bid;

    await this.auctions.saveBid(auction, bid.data);
    this.broadcaster.accepted(auctionId, bid.data);
    return bid;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection, ObjectId } from 'mongodb';
import { Server } from 'socket.io';

interface AuctionDoc {
  _id: ObjectId; sellerId: string; startingPrice: number; endsAt: Date;
  highestBid?: number; highestBidderId?: string;
}

export class MongoAuctionRepository implements AuctionRepository {
  constructor(private readonly auctions: Collection<AuctionDoc>) {}

  async findById(id: string): Promise<Auction | null> {
    const d = await this.auctions.findOne({ _id: new ObjectId(id) });
    if (!d) return null;
    const highest = d.highestBid !== undefined && d.highestBidderId !== undefined
      ? { amount: d.highestBid, bidderId: d.highestBidderId } : null;
    return new Auction(id, d.sellerId, d.startingPrice, d.endsAt, highest);
  }

  async saveBid(auction: Auction, bid: AcceptedBid): Promise<void> {
    await this.auctions.updateOne({ _id: new ObjectId(auction.id) },
      { $set: { highestBid: bid.amount, highestBidderId: bid.bidderId, endsAt: bid.endsAt } });
  }
}

export class SocketBidBroadcaster implements BidBroadcaster {
  constructor(private readonly io: Server) {}
  accepted(auctionId: string, bid: AcceptedBid): void { this.io.to(auctionId).emit('bid:accepted', bid); }
}
