Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import express from 'express';
import { Pool } from 'pg';

const pool = new Pool();
export const router = express.Router();

router.post('/prescriptions/:id/refill', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM prescriptions WHERE id = $1', [req.params.id]);
  const rx = rows[0];
  if (!rx) return res.status(404).send('Not found');
  if (rx.refills_left <= 0) return res.status(409).send('No refills left');
  if (new Date(rx.expires_at) < new Date()) return res.status(410).send('Prescription expired');
  const daysSinceLast = (Date.now() - new Date(rx.last_filled_at).getTime()) / 86400000;
  if (daysSinceLast < rx.days_supply * 0.75) return res.status(429).send('Too early to refill');
  await pool.query(
    'UPDATE prescriptions SET refills_left = refills_left - 1, last_filled_at = now() WHERE id = $1',
    [rx.id],
  );
  res.json({ refillsLeft: rx.refills_left - 1 });
});

```

### Architectural Flaws in Original Code
1. **Clinical rules in a router:** refill count, expiry and the 75%-of-supply waiting period are only reachable through Express.
2. **SQL rows as the model:** `rx.refills_left` and friends are untyped database columns.
3. **Two clocks:** `new Date()` in the handler and `now()` in SQL can disagree.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Prescription.ts`)
```typescript
import { Result } from '../shared/Result';

export type RefillError =
  | { kind: 'NotFound' }
  | { kind: 'NoRefillsLeft' }
  | { kind: 'Expired' }
  | { kind: 'TooEarly'; earliest: Date };

export class Prescription {
  static readonly EARLY_REFILL_RATIO = 0.75;

  constructor(
    readonly id: string,
    private refillsLeft: number,
    readonly expiresAt: Date,
    private lastFilledAt: Date,
    readonly daysSupply: number,
  ) {}

  get remainingRefills(): number { return this.refillsLeft; }
  get lastFilled(): Date { return this.lastFilledAt; }

  refill(now: Date): Result<void, RefillError> {
    if (this.refillsLeft <= 0) return Result.fail({ kind: 'NoRefillsLeft' });
    if (this.expiresAt < now) return Result.fail({ kind: 'Expired' });
    const waitMs = this.daysSupply * Prescription.EARLY_REFILL_RATIO * 86_400_000;
    const earliest = new Date(this.lastFilledAt.getTime() + waitMs);
    if (now < earliest) return Result.fail({ kind: 'TooEarly', earliest });
    this.refillsLeft -= 1;
    this.lastFilledAt = now;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/RefillPrescription.ts`)
```typescript
import { Result } from '../shared/Result';
import { Prescription, RefillError } from '../domain/Prescription';

export interface PrescriptionRepository {
  findById(id: string): Promise<Prescription | null>;
  save(prescription: Prescription): Promise<void>;
}

export class RefillPrescription {
  constructor(private readonly prescriptions: PrescriptionRepository, private readonly now: () => Date) {}

  async execute(id: string): Promise<Result<number, RefillError>> {
    const rx = await this.prescriptions.findById(id);
    if (!rx) return Result.fail({ kind: 'NotFound' });
    const refilled = rx.refill(this.now());
    if (!refilled.success) return refilled;
    await this.prescriptions.save(rx);
    return Result.ok(rx.remainingRefills);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PgPrescriptionRepository.ts`)
```typescript
import { Pool } from 'pg';
import { Prescription } from '../domain/Prescription';
import { PrescriptionRepository } from '../application/RefillPrescription';

interface PrescriptionRow {
  id: string; refills_left: number; expires_at: Date; last_filled_at: Date; days_supply: number;
}

export class PgPrescriptionRepository implements PrescriptionRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Prescription | null> {
    const { rows } = await this.pool.query<PrescriptionRow>('SELECT * FROM prescriptions WHERE id = $1', [id]);
    const r = rows[0];
    return r ? new Prescription(r.id, r.refills_left, r.expires_at, r.last_filled_at, r.days_supply) : null;
  }

  async save(rx: Prescription): Promise<void> {
    await this.pool.query('UPDATE prescriptions SET refills_left = $2, last_filled_at = $3 WHERE id = $1',
      [rx.id, rx.remainingRefills, rx.lastFilled]);
  }
}
```

#### 4. Presentation Layer (`src/http/prescriptionRouter.ts`)
```typescript
import express from 'express';
import { RefillError } from '../domain/Prescription';
import { RefillPrescription } from '../application/RefillPrescription';

function toHttp(error: RefillError): [number, string] {
  switch (error.kind) {
    case 'NotFound': return [404, 'Not found'];
    case 'NoRefillsLeft': return [409, 'No refills left'];
    case 'Expired': return [410, 'Prescription expired'];
    case 'TooEarly': return [429, 'Too early to refill'];
  }
}

export function prescriptionRouter(refill: RefillPrescription): express.Router {
  const router = express.Router();
  router.post('/prescriptions/:id/refill', async (req, res) => {
    const result = await refill.execute(req.params.id);
    if (result.success) return res.json({ refillsLeft: result.data });
    const [status, message] = toHttp(result.error);
    res.status(status).send(message);
  });
  return router;
}
```
The router is now built from an injected use case; the `Pool` is created only in the composition root.

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly customerId: string;
  readonly planId: string;
  readonly startDate: Date;
  readonly endDate: Date;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class SubscriptionStatusError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionStatusError';
  }
}

export class SubscriptionValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionValidationError';
  }
}

// Domain/ValueObjects/SubscriptionValidator.ts
export class SubscriptionValidator {
  static validateCancelSubscription(subscription: Subscription): void {
    if (subscription.status === 'expired') {
      throw new SubscriptionStatusError('Cannot cancel an expired subscription');
    }

    if (subscription.status === 'cancelled') {
      throw new SubscriptionStatusError('Subscription is already cancelled');
    }
  }
